/workspace/main.go.content:
package main

import (
	"errors"
	"fmt"
	"os"
	"time"

	"github.com/spf13/cobra"
)

type verbatimError struct {
	msg string
}

func (e *verbatimError) Error() string {
	return e.msg
}

type configFlags struct {
	Config string
	Env    string
	Vars   []string
}

type inspectOptions struct {
	URL     string
	DevURL  string
	Schemas []string
	Exclude []string
	Format  string
}

type applyOptions struct {
	URL         string
	To          []string
	Exclude     []string
	Include     []string
	Schemas     []string
	DevURL      string
	DryRun      bool
	AutoApprove bool
	Format      string
	TxMode      string
	Plan        string
	Edit        bool
	LockTimeout time.Duration
}

type diffOptions struct {
	From    []string
	To      []string
	DevURL  string
	Schemas []string
	Exclude []string
	Include []string
	Format  string
}

type cleanOptions struct {
	URL         string
	DryRun      bool
	Format      string
	AutoApprove bool
}

func main() {
	if len(os.Args) == 2 && os.Args[1] == "--version" {
		fmt.Fprintln(os.Stderr, "Error: unknown flag: --version")
		fmt.Fprintln(os.Stderr, "You're running the community build of Atlas, which may differ from the official version.")
		fmt.Fprintln(os.Stderr, "If this error persists, try installing the official version as a troubleshooting step:")
		fmt.Fprintln(os.Stderr)
		fmt.Fprintln(os.Stderr, "  curl -sSf https://atlasgo.sh | sh")
		fmt.Fprintln(os.Stderr)
		fmt.Fprintln(os.Stderr, "More installation options: https://atlasgo.io/docs#installation")
		os.Exit(1)
	}

	root := buildRootCommand()
	if err := root.Execute(); err != nil {
		var raw *verbatimError
		if errors.As(err, &raw) {
			fmt.Fprintln(os.Stderr, raw.msg)
		} else {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		}
		os.Exit(1)
	}
}

func buildRootCommand() *cobra.Command {
	root := &cobra.Command{
		Use:           "atlas",
		Short:         "Manage your database schema as code",
		SilenceErrors: true,
		SilenceUsage:  true,
		RunE: func(cmd *cobra.Command, args []string) error {
			return cmd.Help()
		},
	}

	root.SetOut(os.Stdout)
	root.SetErr(os.Stderr)
	root.Flags().SortFlags = false
	root.PersistentFlags().SortFlags = false

	root.AddCommand(buildLicenseCommand())
	root.AddCommand(buildVersionCommand())
	root.AddCommand(buildSchemaCommand())
	root.AddCommand(buildMigrateCommand())

	root.CompletionOptions.DisableDefaultCmd = false
	root.InitDefaultCompletionCmd()
	root.InitDefaultHelpCmd()

	return root
}

func buildLicenseCommand() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "license",
		Short: "Display license information",
		RunE: func(cmd *cobra.Command, args []string) error {
			fmt.Fprintln(cmd.OutOrStdout(), "LICENSE")
			fmt.Fprintln(cmd.OutOrStdout(), "Atlas is licensed under Apache 2.0 as found in https://github.com/ariga/atlas/blob/master/LICENSE.")
			return nil
		},
	}
	cmd.Flags().SortFlags = false
	return cmd
}

func buildVersionCommand() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "version",
		Short: "Prints this Atlas CLI version information.",
		RunE: func(cmd *cobra.Command, args []string) error {
			fmt.Fprintln(cmd.OutOrStdout(), "atlas unofficial version - development")
			fmt.Fprintln(cmd.OutOrStdout(), "https://github.com/ariga/atlas/releases/latest")
			fmt.Fprintln(cmd.OutOrStdout(), "To download an official version, visit: https://atlasgo.io/getting-started#installation")
			return nil
		},
	}
	cmd.Flags().SortFlags = false
	return cmd
}

func buildSchemaCommand() *cobra.Command {
	cfg := &configFlags{}

	cmd := &cobra.Command{
		Use:   "schema",
		Short: "Work with atlas schemas.",
		Long:  "The `atlas schema` command groups subcommands working with declarative Atlas schemas.",
		RunE: func(cmd *cobra.Command, args []string) error {
			return cmd.Help()
		},
	}
	cmd.Flags().SortFlags = false
	cmd.PersistentFlags().SortFlags = false
	cmd.PersistentFlags().StringVarP(&cfg.Config, "config", "c", "file://atlas.hcl", "select config (project) file using URL format")
	cmd.PersistentFlags().StringVar(&cfg.Env, "env", "", "set which env from the config file to use")
	cmd.PersistentFlags().StringArrayVar(&cfg.Vars, "var", nil, "`<name>=<value>` input variables")

	cmd.AddCommand(buildSchemaFmtCommand(cfg))
	cmd.AddCommand(buildSchemaInspectCommand(cfg))
	cmd.AddCommand(buildSchemaApplyCommand(cfg))
	cmd.AddCommand(buildSchemaDiffCommand(cfg))
	cmd.AddCommand(buildSchemaCleanCommand(cfg))

	return cmd
}

func buildSchemaFmtCommand(cfg *configFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "fmt [path ...]",
		Short: "Formats Atlas HCL files",
		Long: "'atlas schema fmt' formats all \".hcl\" files under the given paths using\n" +
			"canonical HCL layout style as defined by the github.com/hashicorp/hcl/v2/hclwrite package.\n" +
			"Unless stated otherwise, the fmt command will use the current directory.\n\n" +
			"After running, the command will print the names of the files it has formatted. If all\n" +
			"files in the directory are formatted, no input will be printed out.",
		RunE: func(cmd *cobra.Command, args []string) error {
			return runSchemaFmt(cmd, args)
		},
	}
	cmd.Flags().SortFlags = false
	return cmd
}

func buildSchemaInspectCommand(cfg *configFlags) *cobra.Command {
	opts := &inspectOptions{}
	cmd := &cobra.Command{
		Use:   "inspect",
		Short: "Inspect a database and print its schema in Atlas DDL syntax.",
		Long: "'atlas schema inspect' connects to the given database and inspects its schema.\n" +
			"It then prints to the screen the schema of that database in Atlas DDL syntax. This output can be\n" +
			"saved to a file, commonly by redirecting the output to a file named with a \".hcl\" suffix:\n\n" +
			"  atlas schema inspect -u \"mysql://user:pass@localhost:3306/dbname\" > schema.hcl\n\n" +
			"This file can then be edited and used with the `atlas schema apply` command to plan\n" +
			"and execute schema migrations against the given database. In cases where users wish to inspect\n" +
			"all multiple schemas in a given database (for instance a MySQL server may contain multiple named\n" +
			"databases), omit the relevant part from the url, e.g. \"mysql://user:pass@localhost:3306/\".\n" +
			"To select specific schemas from the databases, users may use the \"--schema\" (or \"-s\" shorthand)\n" +
			"flag.",
		Example: "  atlas schema inspect -u \"mysql://user:pass@localhost:3306/dbname\"\n" +
			"  atlas schema inspect -u \"mariadb://user:pass@localhost:3306/\" --schema=schemaA,schemaB -s schemaC\n" +
			"  atlas schema inspect --url \"postgres://user:pass@host:port/dbname?sslmode=disable\"\n" +
			"  atlas schema inspect -u \"sqlite://file:ex1.db?_fk=1\"",
		RunE: func(cmd *cobra.Command, args []string) error {
			return runSchemaInspect(cmd, cfg, *opts)
		},
	}
	cmd.Flags().SortFlags = false
	cmd.Flags().StringVarP(&opts.URL, "url", "u", "", "[driver://username:password@address/dbname?param=value] select a resource using the URL format")
	cmd.Flags().StringVar(&opts.DevURL, "dev-url", "", "[driver://username:password@address/dbname?param=value] select a dev database using the URL format")
	cmd.Flags().StringSliceVarP(&opts.Schemas, "schema", "s", nil, "set schema names")
	cmd.Flags().StringSliceVar(&opts.Exclude, "exclude", nil, "list of glob patterns used to filter resources from applying")
	cmd.Flags().StringVar(&opts.Format, "format", "", "Go template to use to format the output")
	return cmd
}

func buildSchemaApplyCommand(cfg *configFlags) *cobra.Command {
	opts := &applyOptions{TxMode: "file", LockTimeout: 10 * time.Second}
	cmd := &cobra.Command{
		Use:   "apply",
		Short: "Apply an atlas schema to a target database.",
		Long: "'atlas schema apply' plans and executes a database migration to bring a given\n" +
			"database to the state described in the provided Atlas schema. Before running the\n" +
			"migration, Atlas will print the migration plan and prompt the user for approval.\n\n" +
			"The schema is provided by one or more URLs (to a HCL file or \n" +
			"directory, database or migration directory) using the \"--to, -t\" flag:\n" +
			"  atlas schema apply -u URL --to \"file://file1.hcl\" --to \"file://file2.hcl\"\n" +
			"  atlas schema apply -u URL --to \"file://schema/\" --to \"file://override.hcl\"\n\n" +
			"As a convenience, schema URLs may also be provided via an environment definition in\n" +
			"the project file (see: https://atlasgo.io/cli/projects).\n\n" +
			"If run with the \"--dry-run\" flag, atlas will exit after printing out the planned\n" +
			"migration.",
		Example: "  atlas schema apply -u \"mysql://user:pass@localhost/dbname\" --to \"file://atlas.hcl\"\n" +
			"  atlas schema apply -u \"mysql://localhost\" --to \"file://schema.sql\" --dev-url \"docker://mysql/8/dev\"\n" +
			"  atlas schema apply --env local --dev-url \"docker://postgres/15/dev?search_path=public\" --dry-run\n" +
			"  atlas schema apply -u \"sqlite://file.db\" --to \"file://schema.sql\" --dev-url \"sqlite://dev?mode=memory\"",
		RunE: func(cmd *cobra.Command, args []string) error {
			return runSchemaApply(cmd, cfg, *opts)
		},
	}
	cmd.Flags().SortFlags = false
	cmd.Flags().StringVarP(&opts.URL, "url", "u", "", "[driver://username:password@address/dbname?param=value] select a resource using the URL format")
	cmd.Flags().StringSliceVar(&opts.To, "to", nil, "[driver://username:password@address/dbname?param=value] select a desired state using the URL format")
	cmd.Flags().StringSliceVar(&opts.Exclude, "exclude", nil, "list of glob patterns used to filter resources from applying")
	cmd.Flags().StringSliceVar(&opts.Include, "include", nil, "list of glob patterns used to select which resources to keep in inspection")
	cmd.Flags().StringSliceVarP(&opts.Schemas, "schema", "s", nil, "set schema names")
	cmd.Flags().StringVar(&opts.DevURL, "dev-url", "", "[driver://username:password@address/dbname?param=value] select a dev database using the URL format")
	cmd.Flags().BoolVar(&opts.DryRun, "dry-run", false, "print SQL without executing it")
	cmd.Flags().BoolVar(&opts.AutoApprove, "auto-approve", false, "apply changes without prompting for approval")
	cmd.Flags().StringVar(&opts.Format, "format", "", "Go template to use to format the output")
	cmd.Flags().StringVar(&opts.TxMode, "tx-mode", "file", "set transaction mode [none, file]")
	cmd.Flags().StringVar(&opts.Plan, "plan", "", "URL to a pre-planned migration (e.g., atlas://repo/plans/name)")
	cmd.Flags().BoolVar(&opts.Edit, "edit", false, "open the generated SQL in an editor")
	cmd.Flags().DurationVar(&opts.LockTimeout, "lock-timeout", 10*time.Second, "set how long to wait for the database lock")
	return cmd
}

func buildSchemaDiffCommand(cfg *configFlags) *cobra.Command {
	opts := &diffOptions{}
	cmd := &cobra.Command{
		Use:   "diff",
		Short: "Calculate and print the diff between two schemas.",
		Long: "'atlas schema diff' reads the state of two given schema definitions, \n" +
			"calculates the difference in their schemas, and prints a plan of\n" +
			"SQL statements to migrate the \"from\" database to the schema of the \"to\" database.\n" +
			"The database states can be read from a connected database, an HCL project or a migration directory.",
		Example: "  atlas schema diff --from \"mysql://user:pass@localhost:3306/test\" --to \"file://schema.hcl\"\n" +
			"  atlas schema diff --from \"mysql://user:pass@localhost:3306\" --to \"file://schema_1.hcl\" --to \"file://schema_2.hcl\"\n" +
			"  atlas schema diff --from \"mysql://user:pass@localhost:3306\" --to \"file://migrations\" --format '{{ sql . \"  \" }}'",
		RunE: func(cmd *cobra.Command, args []string) error {
			return runSchemaDiff(cmd, cfg, *opts)
		},
	}
	cmd.Flags().SortFlags = false
	cmd.Flags().StringSliceVarP(&opts.From, "from", "f", nil, "[driver://username:password@address/dbname?param=value] select a resource using the URL format")
	cmd.Flags().StringSliceVar(&opts.To, "to", nil, "[driver://username:password@address/dbname?param=value] select a desired state using the URL format")
	cmd.Flags().StringVar(&opts.DevURL, "dev-url", "", "[driver://username:password@address/dbname?param=value] select a dev database using the URL format")
	cmd.Flags().StringSliceVarP(&opts.Schemas, "schema", "s", nil, "set schema names")
	cmd.Flags().StringSliceVar(&opts.Exclude, "exclude", nil, "list of glob patterns used to filter resources from applying")
	cmd.Flags().StringSliceVar(&opts.Include, "include", nil, "list of glob patterns used to select which resources to keep in inspection")
	cmd.Flags().StringVar(&opts.Format, "format", "", "Go template to use to format the output")
	return cmd
}

func buildSchemaCleanCommand(cfg *configFlags) *cobra.Command {
	opts := &cleanOptions{}
	cmd := &cobra.Command{
		Use:   "clean",
		Short: "Removes all objects from the connected database.",
		Long: "'atlas schema clean' drops all objects in the connected database and leaves it in an empty state.\n" +
			"As a safety feature, 'atlas schema clean' will ask for confirmation before attempting to execute any SQL.",
		Example: "  atlas schema clean -u \"mysql://user:pass@localhost:3306/dbname\"\n" +
			"  atlas schema clean -u \"mysql://user:pass@localhost:3306/\"",
		RunE: func(cmd *cobra.Command, args []string) error {
			return runSchemaClean(cmd, cfg, *opts)
		},
	}
	cmd.Flags().SortFlags = false
	cmd.Flags().StringVarP(&opts.URL, "url", "u", "", "[driver://username:password@address/dbname?param=value] select a resource using the URL format")
	cmd.Flags().BoolVar(&opts.DryRun, "dry-run", false, "print SQL without executing it")
	cmd.Flags().StringVar(&opts.Format, "format", "", "Go template to use to format the output")
	cmd.Flags().BoolVar(&opts.AutoApprove, "auto-approve", false, "apply changes without prompting for approval")
	return cmd
}

func buildMigrateCommand() *cobra.Command {
	cfg := &configFlags{}
	cmd := &cobra.Command{
		Use:   "migrate",
		Short: "Manage versioned migration files",
		Long:  "'atlas migrate' wraps several sub-commands for migration management.",
		RunE: func(cmd *cobra.Command, args []string) error {
			return cmd.Help()
		},
	}
	cmd.Flags().SortFlags = false
	cmd.PersistentFlags().SortFlags = false
	cmd.PersistentFlags().StringVarP(&cfg.Config, "config", "c", "file://atlas.hcl", "select config (project) file using URL format")
	cmd.PersistentFlags().StringVar(&cfg.Env, "env", "", "set which env from the config file to use")
	cmd.PersistentFlags().StringArrayVar(&cfg.Vars, "var", nil, "`<name>=<value>` input variables")

	addStub := func(use, short string) {
		child := &cobra.Command{
			Use:   use,
			Short: short,
			RunE: func(cmd *cobra.Command, args []string) error {
				return cmd.Help()
			},
		}
		child.Flags().SortFlags = false
		cmd.AddCommand(child)
	}

	addStub("apply", "Applies pending migration files on the connected database.")
	addStub("diff", "Compute the diff between the migration directory and a desired state and create a new migration file.")
	addStub("hash", "Hash (re-)creates an integrity hash file for the migration directory.")
	addStub("import", "Import a migration directory from another migration management tool to the Atlas format.")
	addStub("lint", "Run analysis on the migration directory")
	addStub("new", "Creates a new empty migration file in the migration directory.")
	addStub("set", "Set the current version of the migration history table.")
	addStub("status", "Get information about the current migration status.")
	addStub("validate", "Validates the migration directories checksum and SQL statements.")

	return cmd
}

