package main

import (
	"bufio"
	"bytes"
	"database/sql"
	"encoding/json"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"text/template"

	_ "modernc.org/sqlite"

	"github.com/hashicorp/hcl/v2/hclsyntax"
	"github.com/hashicorp/hcl/v2/hclwrite"
	"github.com/spf13/cobra"
)

type state struct {
	SchemaName string
	Tables     []table
}

type table struct {
	Name       string
	Columns    []column
	PrimaryKey []string
}

type column struct {
	Name    string
	Type    string
	RawType string
	NotNull bool
}

type operationKind string

const (
	opCreate operationKind = "create"
	opDrop   operationKind = "drop"
)

type operation struct {
	Kind  operationKind
	Table table
}

type resourceRef struct {
	Scheme string
	Body   string
}

func runSchemaFmt(cmd *cobra.Command, args []string) error {
	if len(args) == 0 {
		args = []string{"."}
	}
	for _, arg := range args {
		info, err := os.Stat(arg)
		if err != nil {
			return err
		}
		if info.IsDir() {
			entries, err := os.ReadDir(arg)
			if err != nil {
				return err
			}
			for _, entry := range entries {
				if entry.IsDir() || filepath.Ext(entry.Name()) != ".hcl" {
					continue
				}
				path := filepath.Join(arg, entry.Name())
				changed, err := formatHCLFile(path)
				if err != nil {
					return err
				}
				if changed {
					fmt.Fprintln(cmd.OutOrStdout(), path)
				}
			}
			continue
		}
		if filepath.Ext(arg) != ".hcl" {
			continue
		}
		changed, err := formatHCLFile(arg)
		if err != nil {
			return err
		}
		if changed {
			fmt.Fprintln(cmd.OutOrStdout(), arg)
		}
	}
	return nil
}

func formatHCLFile(path string) (bool, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return false, err
	}
	formatted := hclwrite.Format(src)
	if bytes.Equal(src, formatted) {
		return false, nil
	}
	if err := os.WriteFile(path, formatted, 0o644); err != nil {
		return false, err
	}
	return true, nil
}

func runSchemaInspect(cmd *cobra.Command, cfg *configFlags, opts inspectOptions) error {
	env, err := resolveProjectEnv(cfg)
	if err != nil {
		return err
	}
	if opts.URL == "" {
		opts.URL = env.URL
	}
	if opts.DevURL == "" {
		opts.DevURL = env.DevURL
	}
	if len(opts.Schemas) == 0 && len(env.Schemas) > 0 {
		opts.Schemas = append(opts.Schemas, env.Schemas...)
	}
	if opts.URL == "" {
		return requiredFlagsError("url")
	}

	ref, err := parseResource(opts.URL)
	if err != nil {
		return err
	}

	switch ref.Scheme {
	case "sqlite":
		db, foreignKeys, err := openSQLite(ref.Body)
		if err != nil {
			return err
		}
		defer db.Close()
		if foreignKeys {
			if _, err := db.Exec(`PRAGMA foreign_keys = on`); err != nil {
				return err
			}
		}
		st, err := inspectSQLite(db)
		if err != nil {
			return err
		}
		out, err := renderState(st, opts.Format)
		if err != nil {
			return err
		}
		fmt.Fprint(cmd.OutOrStdout(), out)
		return nil
	default:
		return fmt.Errorf("unsupported driver %q", ref.Scheme)
	}
}

func runSchemaApply(cmd *cobra.Command, cfg *configFlags, opts applyOptions) error {
	env, err := resolveProjectEnv(cfg)
	if err != nil {
		return err
	}
	if opts.URL == "" {
		opts.URL = env.URL
	}
	if opts.DevURL == "" {
		opts.DevURL = env.DevURL
	}
	if len(opts.Schemas) == 0 && len(env.Schemas) > 0 {
		opts.Schemas = append(opts.Schemas, env.Schemas...)
	}
	if opts.URL == "" {
		return requiredFlagsError("url")
	}
	if len(opts.To) == 0 {
		return requiredFlagsError("to")
	}

	targetRef, err := parseResource(opts.URL)
	if err != nil {
		return err
	}
	if targetRef.Scheme != "sqlite" {
		return fmt.Errorf("unsupported driver %q", targetRef.Scheme)
	}

	desired, err := loadStateFromResources(opts.To)
	if err != nil {
		return err
	}
	if err := ensureSchemaMatch("main", desired); err != nil {
		return err
	}

	db, foreignKeys, err := openSQLite(targetRef.Body)
	if err != nil {
		return err
	}
	defer db.Close()
	if foreignKeys {
		if _, err := db.Exec(`PRAGMA foreign_keys = on`); err != nil {
			return err
		}
	}
	current, err := inspectSQLite(db)
	if err != nil {
		return err
	}

	ops := diffStates(current, desired)
	if len(ops) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "Schema is synced, no changes to be made")
		return nil
	}

	fmt.Fprint(cmd.OutOrStdout(), renderPlanPretty(ops))
	if opts.DryRun {
		return nil
	}
	if !opts.AutoApprove {
		ok, err := confirmApply()
		if err != nil {
			return err
		}
		if !ok {
			return nil
		}
	}
	return applyOperations(db, ops)
}

func runSchemaDiff(cmd *cobra.Command, cfg *configFlags, opts diffOptions) error {
	_, err := resolveProjectEnv(cfg)
	if err != nil {
		return err
	}
	if len(opts.From) == 0 {
		return requiredFlagsError("from")
	}
	if len(opts.To) == 0 {
		return requiredFlagsError("to")
	}

	fromState, fromSchema, err := loadStateWithSchema(opts.From[0])
	if err != nil {
		return err
	}
	toState, err := loadStateFromResources(opts.To)
	if err != nil {
		return err
	}
	if fromSchema == "main" {
		if err := ensureSchemaMatch(fromSchema, toState); err != nil {
			return err
		}
	}

	ops := diffStates(fromState, toState)
	if len(ops) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "Schemas are synced, no changes to be made.")
		return nil
	}
	fmt.Fprint(cmd.OutOrStdout(), renderPlanCompact(ops))
	return nil
}

