package main

import (
	"fmt"
	"os"
	"sort"
	"strings"

	"github.com/hashicorp/hcl/v2"
	"github.com/hashicorp/hcl/v2/hclparse"
	"github.com/hashicorp/hcl/v2/hclsyntax"
	"github.com/zclconf/go-cty/cty"
	_jsii "github.com/zclconf/go-cty/cty/function"
)

type projectEnv struct {
	URL     string
	DevURL  string
	Schemas []string
}

func resolveProjectEnv(cfg *configFlags) (projectEnv, error) {
	if cfg == nil || cfg.Env == "" {
		return projectEnv{}, nil
	}

	path, err := parseConfigPath(cfg.Config)
	if err != nil {
		return projectEnv{}, err
	}
	src, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return projectEnv{}, fmt.Errorf("config file %q was not found: %w", path, err)
		}
		return projectEnv{}, err
	}

	parser := hclparse.NewParser()
	file, diags := parser.ParseHCL(src, path)
	if diags.HasErrors() {
		return projectEnv{}, fmt.Errorf(diags.Error())
	}

	body, ok := file.Body.(*hclsyntax.Body)
	if !ok {
		return projectEnv{}, fmt.Errorf("unsupported config body")
	}

	vars, err := evaluateVariables(body, cfg.Vars)
	if err != nil {
		return projectEnv{}, err
	}

	locals, err := evaluateLocals(body, cfg.Env, vars)
	if err != nil {
		return projectEnv{}, err
	}

	env, ok := findEnv(body, cfg.Env, vars, locals)
	if !ok {
		return projectEnv{}, fmt.Errorf("env %q not defined in config file", cfg.Env)
	}
	return env, nil
}

func parseConfigPath(spec string) (string, error) {
	idx := strings.Index(spec, "://")
	if idx < 0 {
		return "", fmt.Errorf("missing scheme for config file. Did you mean file://%s?", spec)
	}
	scheme, rest := spec[:idx], spec[idx+3:]
	if scheme != "file" {
		return "", fmt.Errorf("unsupported config file driver %q", scheme)
	}
	return rest, nil
}

func evaluateVariables(body *hclsyntax.Body, inputs []string) (map[string]cty.Value, error) {
	overrides := map[string]string{}
	for _, item := range inputs {
		name, value, ok := strings.Cut(item, "=")
		if !ok || name == "" {
			return nil, fmt.Errorf("invalid variable assignment %q", item)
		}
		overrides[name] = value
	}

	vars := map[string]cty.Value{}
	for _, block := range body.Blocks {
		if block.Type != "variable" || len(block.Labels) == 0 {
			continue
		}
		name := block.Labels[0]
		if override, ok := overrides[name]; ok {
			vars[name] = cty.StringVal(override)
			continue
		}
		attr, ok := block.Body.Attributes["default"]
		if !ok {
			vars[name] = cty.StringVal("")
			continue
		}
		val, diags := attr.Expr.Value(&hcl.EvalContext{})
		if diags.HasErrors() {
			return nil, fmt.Errorf(diags.Error())
		}
		vars[name] = val
	}
	for name, value := range overrides {
		if _, ok := vars[name]; !ok {
			vars[name] = cty.StringVal(value)
		}
	}
	return vars, nil
}

func evaluateLocals(body *hclsyntax.Body, envName string, vars map[string]cty.Value) (map[string]cty.Value, error) {
	localAttrs := map[string]*hclsyntax.Attribute{}
	for _, block := range body.Blocks {
		if block.Type != "locals" {
			continue
		}
		for name, attr := range block.Body.Attributes {
			localAttrs[name] = attr
		}
	}

	locals := map[string]cty.Value{}
	if len(localAttrs) == 0 {
		return locals, nil
	}

	keys := make([]string, 0, len(localAttrs))
	for name := range localAttrs {
		keys = append(keys, name)
	}
	sort.Strings(keys)

	pending := map[string]*hclsyntax.Attribute{}
	for _, name := range keys {
		pending[name] = localAttrs[name]
	}

	for len(pending) > 0 {
		progress := false
		for _, name := range keys {
			attr, ok := pending[name]
			if !ok {
				continue
			}
			ctx := newEvalContext(envName, vars, locals)
			val, diags := attr.Expr.Value(ctx)
			if diags.HasErrors() {
				continue
			}
			locals[name] = val
			delete(pending, name)
			progress = true
		}
		if progress {
			continue
		}
		for _, name := range keys {
			attr, ok := pending[name]
			if !ok {
				continue
			}
			_, diags := attr.Expr.Value(newEvalContext(envName, vars, locals))
			if diags.HasErrors() {
				return nil, fmt.Errorf(diags.Error())
			}
		}
		break
	}

	return locals, nil
}

func findEnv(body *hclsyntax.Body, envName string, vars, locals map[string]cty.Value) (projectEnv, bool) {
	for _, block := range body.Blocks {
		if block.Type != "env" || len(block.Labels) == 0 || block.Labels[0] != envName {
			continue
		}
		ctx := newEvalContext(envName, vars, locals)
		env := projectEnv{}
		if attr, ok := block.Body.Attributes["url"]; ok {
			val, diags := attr.Expr.Value(ctx)
			if diags.HasErrors() {
				return projectEnv{}, false
			}
			env.URL = ctyToString(val)
		}
		if attr, ok := block.Body.Attributes["dev"]; ok {
			val, diags := attr.Expr.Value(ctx)
			if diags.HasErrors() {
				return projectEnv{}, false
			}
			env.DevURL = ctyToString(val)
		}
		if attr, ok := block.Body.Attributes["schemas"]; ok {
			val, diags := attr.Expr.Value(ctx)
			if diags.HasErrors() {
				return projectEnv{}, false
			}
			if val.Type().IsTupleType() || val.Type().IsListType() || val.Type().IsSetType() {
				it := val.ElementIterator()
				for it.Next() {
					_, item := it.Element()
					env.Schemas = append(env.Schemas, ctyToString(item))
				}
			}
		}
		return env, true
	}
	return projectEnv{}, false
}

func newEvalContext(envName string, vars, locals map[string]cty.Value) *hcl.EvalContext {
	varObj := cty.ObjectVal(map[string]cty.Value{})
	if len(vars) > 0 {
		varObj = cty.ObjectVal(vars)
	}
	localObj := cty.ObjectVal(map[string]cty.Value{})
	if len(locals) > 0 {
		localObj = cty.ObjectVal(locals)
	}
	return &hcl.EvalContext{
		Variables: map[string]cty.Value{
			"var":   varObj,
			"local": localObj,
			"atlas": cty.ObjectVal(map[string]cty.Value{
				"env": cty.StringVal(envName),
			}),
		},
		Functions: map[string]function{
			"getenv": newGetenvFunc(),
		},
	}
}

type function = *_jsii.Function

func newGetenvFunc() function {
	return _jsii.New(&_jsii.Spec{
		Params: []_jsii.Parameter{
			{Name: "name", Type: cty.String},
		},
		Type: _jsii.StaticReturnType(cty.String),
		Impl: func(args []cty.Value, retType cty.Type) (cty.Value, error) {
			return cty.StringVal(os.Getenv(args[0].AsString())), nil
		},
	})
}

func ctyToString(v cty.Value) string {
	if !v.IsKnown() || v.IsNull() {
		return ""
	}
	switch {
	case v.Type() == cty.String:
		return v.AsString()
	case v.Type() == cty.Number:
		bf := v.AsBigFloat()
		return bf.Text('f', -1)
	case v.Type() == cty.Bool:
		if v.True() {
			return "true"
		}
		return "false"
	default:
		return v.GoString()
	}
}

