+	case "completion":
+		return runCompletion(args[1:])
+	default:
+		if strings.HasPrefix(args[0], "-") {
+			return fmt.Errorf("unknown flag: %s", args[0])
+		}
+		return fmt.Errorf("unknown command %q for %q\nRun 'atlas --help' for usage.", args[0], "atlas")
+	}
+}
