+func runSchemaFmt(args []string) error {
+	flags, err := parseFlags(args, append(projectFlagSpecs(), flagSpec{name: "help", short: "h", kind: flagBool}))
+	if err != nil {
+		return err
+	}
+	if flags.bools["help"] {
+		fmt.Print(schemaFmtHelp)
+		return nil
+	}
+	paths := flags.positionals
+	if len(paths) == 0 {
+		paths = []string{"."}
+	}
+	for _, path := range paths {
+		info, err := os.Stat(path)
+		if err != nil {
+			return err
+		}
+		if info.IsDir() {
+			entries, err := os.ReadDir(path)
+			if err != nil {
+				return err
+			}
+			for _, entry := range entries {
+				if entry.IsDir() || filepath.Ext(entry.Name()) != ".hcl" {
+					continue
+				}
+				target := filepath.Join(path, entry.Name())
+				changed, err := formatHCLPath(target)
+				if err != nil {
+					return err
+				}
+				if changed {
+					fmt.Println(target)
+				}
+			}
+			continue
+		}
+		if filepath.Ext(path) != ".hcl" {
+			continue
+		}
+		changed, err := formatHCLPath(path)
+		if err != nil {
+			return err
+		}
+		if changed {
+			fmt.Println(path)
+		}
+	}
+	return nil
