+		return requiredFlagsError("url")
+	}
+	if len(opts.to) == 0 {
+		return requiredFlagsError("to")
+	}
+	ref, err := parseResource(opts.url)
+	if err != nil {
+		return err
+	}
+	if ref.scheme != "sqlite" {
