+func parseFlags(args []string, specs []flagSpec) (parsedFlags, error) {
+	long := map[string]flagSpec{}
+	short := map[string]flagSpec{}
+	for _, spec := range specs {
+		long[spec.name] = spec
+		if spec.short != "" {
+			short[spec.short] = spec
+		}
+	}
+	out := parsedFlags{
+		bools:      map[string]bool{},
+		strings:    map[string]string{},
+		stringSets: map[string][]string{},
+	}
+	for i := 0; i < len(args); i++ {
+		arg := args[i]
+		if arg == "--" {
+			out.positionals = append(out.positionals, args[i+1:]...)
+			break
+		}
+		if strings.HasPrefix(arg, "--") {
+			name, value, hasValue := strings.Cut(strings.TrimPrefix(arg, "--"), "=")
+			spec, ok := long[name]
+			if !ok {
+				return out, fmt.Errorf("unknown flag: --%s", name)
+			}
+			switch spec.kind {
+			case flagBool:
+				if hasValue {
+					return out, fmt.Errorf("unknown flag: %s", arg)
+				}
+				out.bools[spec.name] = true
+			case flagString, flagStrings:
+				if !hasValue {
+					if i+1 >= len(args) {
+						value = ""
+					} else {
+						i++
+						value = args[i]
+					}
+				}
+				addFlagValue(&out, spec, value)
+			}
+			continue
+		}
+		if strings.HasPrefix(arg, "-") && arg != "-" {
+			name := strings.TrimPrefix(arg, "-")
+			spec, ok := short[name]
+			if !ok {
+				return out, fmt.Errorf("unknown flag: -%s", name)
+			}
+			switch spec.kind {
+			case flagBool:
+				out.bools[spec.name] = true
+			case flagString, flagStrings:
+				value := ""
+				if i+1 < len(args) {
+					i++
+					value = args[i]
+				}
+				addFlagValue(&out, spec, value)
+			}
+			continue
+		}
+		out.positionals = append(out.positionals, arg)
+	}
+	return out, nil
+}
+
+func addFlagValue(flags *parsedFlags, spec flagSpec, value string) {
+	switch spec.kind {
+	case flagString:
+		flags.strings[spec.name] = value
+	case flagStrings:
+		if spec.splitComma {
+			parts := strings.Split(value, ",")
+			for _, part := range parts {
+				if part == "" {
+					continue
+				}
+				flags.stringSets[spec.name] = append(flags.stringSets[spec.name], part)
+			}
+			return
+		}
+		flags.stringSets[spec.name] = append(flags.stringSets[spec.name], value)
+	}
+}
+
+func projectFlagsFrom(flags parsedFlags) projectFlags {
+	return projectFlags{
+		config: pickString(flags.strings["config"], "file://atlas.hcl"),
+		env:    flags.strings["env"],
+		vars:   flags.stringSets["var"],
+	}
+}
+
+func projectFlagSpecs() []flagSpec {
+	return []flagSpec{
+		{name: "help", short: "h", kind: flagBool},
+		{name: "config", short: "c", kind: flagString},
+		{name: "env", kind: flagString},
+		{name: "var", kind: flagStrings},
+	}
+}
+
+func onlyHelp(args []string, specs []flagSpec) bool {
+	for _, arg := range args {
+		if arg == "-h" || arg == "--help" {
+			continue
+		}
+		if strings.HasPrefix(arg, "-") {
+			name := strings.TrimLeft(arg, "-")
+			if strings.Contains(name, "=") {
+				name = strings.SplitN(name, "=", 2)[0]
+			}
+			if isPersistentFlag(name, specs) {
+				continue
+			}
+		}
+		return false
+	}
+	return true
+}
+
+func findSubcommand(args []string, persistent []flagSpec) (int, string, bool, error) {
+	expectValueFor := ""
+	for i, arg := range args {
+		if expectValueFor != "" {
+			expectValueFor = ""
+			continue
+		}
+		if strings.HasPrefix(arg, "--") {
+			name := strings.TrimPrefix(arg, "--")
+			if strings.Contains(name, "=") {
+				name = strings.SplitN(name, "=", 2)[0]
+			} else if isValueFlag(name, persistent) {
+				expectValueFor = name
+			}
+			if arg == "--help" {
+				continue
+			}
+			if !isPersistentFlag(name, persistent) {
+				return 0, "", false, fmt.Errorf("unknown flag: --%s", name)
+			}
+			continue
+		}
+		if strings.HasPrefix(arg, "-") && arg != "-" {
+			name := strings.TrimPrefix(arg, "-")
+			if arg == "-h" {
+				continue
+			}
+			if !isPersistentShort(name, persistent) {
+				return 0, "", false, fmt.Errorf("unknown flag: -%s", name)
+			}
+			if shortNeedsValue(name, persistent) {
+				expectValueFor = name
+			}
+			continue
+		}
+		return i, arg, true, nil
+	}
+	return 0, "", false, nil
+}
+
+func isPersistentFlag(name string, specs []flagSpec) bool {
+	for _, spec := range specs {
+		if spec.name == name {
+			return true
+		}
+	}
+	return false
+}
+
+func isPersistentShort(name string, specs []flagSpec) bool {
+	for _, spec := range specs {
+		if spec.short == name {
+			return true
+		}
+	}
+	return false
+}
+
+func isValueFlag(name string, specs []flagSpec) bool {
+	for _, spec := range specs {
+		if spec.name == name {
+			return spec.kind != flagBool
+		}
+	}
+	return false
+}
+
+func shortNeedsValue(name string, specs []flagSpec) bool {
+	for _, spec := range specs {
+		if spec.short == name {
+			return spec.kind != flagBool
+		}
+	}
+	return false
+}
+
+func isSchemaSubcommand(name string) bool {
+	switch name {
+	case "apply", "clean", "diff", "fmt", "inspect":
+		return true
+	default:
+		return false
+	}
+}
+
+func isMigrateSubcommand(name string) bool {
+	switch name {
