+func renderInspectHCL(st schemaState) string {
+	if len(st.Tables) == 0 {
+		return fmt.Sprintf("schema %q {\n}\n", st.SchemaName)
+	}
+	var blocks []string
+	for _, tbl := range st.Tables {
+		blocks = append(blocks, renderInspectTable(tbl))
+	}
+	blocks = append(blocks, fmt.Sprintf("schema %q {\n}", st.SchemaName))
+	return strings.Join(blocks, "\n") + "\n"
+}
+
+func renderInspectTable(tbl tableDef) string {
+	var b strings.Builder
+	fmt.Fprintf(&b, "table %q {\n", tbl.Name)
+	fmt.Fprintf(&b, "  schema = schema.main\n")
+	for _, col := range tbl.Columns {
+		fmt.Fprintf(&b, "  column %q {\n", col.Name)
+		fmt.Fprintf(&b, "    null = false\n")
+		fmt.Fprintf(&b, "    type = %s\n", normalizeType(col.Type))
+		fmt.Fprintf(&b, "  }\n")
+	}
+	if len(tbl.PrimaryKey) > 0 {
+		fmt.Fprintf(&b, "  primary_key {\n")
+		var cols []string
+		for _, name := range tbl.PrimaryKey {
+			cols = append(cols, "column."+name)
+		}
+		fmt.Fprintf(&b, "    columns = [%s]\n", strings.Join(cols, ", "))
+		fmt.Fprintf(&b, "  }\n")
+	}
+	fmt.Fprintf(&b, "}")
+	return b.String()
+}
+
+func renderInspectSQL(st schemaState) string {
+	var lines []string
+	for _, tbl := range st.Tables {
+		lines = append(lines, fmt.Sprintf("-- create %q table", tbl.Name))
+		lines = append(lines, renderCreateCompact(tbl))
+	}
+	return strings.Join(lines, "\n")
+}
+
+func renderPrettyPlan(ops []schemaOp) string {
+	lines := []string{"-- Planned Changes:"}
+	for _, op := range ops {
+		lines = append(lines, op.Comment())
+		lines = append(lines, op.SQLPretty())
+	}
+	return strings.Join(lines, "\n") + "\n"
+}
+
+func renderCompactPlan(ops []schemaOp) string {
+	lines := make([]string, 0, len(ops)*2)
+	for _, op := range ops {
+		lines = append(lines, op.Comment())
+		lines = append(lines, op.SQLCompact())
+	}
+	return strings.Join(lines, "\n")
+}
+
+func renderCleanPlan(tables []tableDef) string {
+	lines := []string{
+		"-- Planned Changes:",
+		"-- Disable the enforcement of foreign-keys constraints",
+		"PRAGMA foreign_keys = off;",
+	}
+	for _, tbl := range tables {
+		lines = append(lines, fmt.Sprintf("-- Drop %q table", tbl.Name))
+		lines = append(lines, fmt.Sprintf("DROP TABLE `%s`;", tbl.Name))
+	}
+	lines = append(lines, "-- Enable back the enforcement of foreign-keys constraints")
+	lines = append(lines, "PRAGMA foreign_keys = on;")
+	return strings.Join(lines, "\n") + "\n"
+}
+
+func renderCreateCompact(tbl tableDef) string {
+	parts := make([]string, 0, len(tbl.Columns)+1)
+	for _, col := range tbl.Columns {
+		parts = append(parts, fmt.Sprintf("`%s` %s NOT NULL", col.Name, normalizeType(col.Type)))
+	}
+	if len(tbl.PrimaryKey) > 0 {
+		var cols []string
+		for _, name := range tbl.PrimaryKey {
+			cols = append(cols, fmt.Sprintf("`%s`", name))
+		}
+		parts = append(parts, fmt.Sprintf("PRIMARY KEY (%s)", strings.Join(cols, ", ")))
+	}
+	return fmt.Sprintf("CREATE TABLE `%s` (%s);", tbl.Name, strings.Join(parts, ", "))
+}
+
+func renderCreatePretty(tbl tableDef) string {
+	lines := []string{fmt.Sprintf("CREATE TABLE `%s` (", tbl.Name)}
+	for i, col := range tbl.Columns {
+		suffix := ","
+		if i == len(tbl.Columns)-1 && len(tbl.PrimaryKey) == 0 {
+			suffix = ""
+		}
+		lines = append(lines, fmt.Sprintf("  `%s` %s NOT NULL%s", col.Name, normalizeType(col.Type), suffix))
+	}
+	if len(tbl.PrimaryKey) > 0 {
+		var cols []string
+		for _, name := range tbl.PrimaryKey {
+			cols = append(cols, fmt.Sprintf("`%s`", name))
+		}
+		lines = append(lines, fmt.Sprintf("  PRIMARY KEY (%s)", strings.Join(cols, ", ")))
+	}
+	lines = append(lines, ");")
+	return strings.Join(lines, "\n")
+}
+
+func normalizeType(t string) string {
+	lower := strings.ToLower(strings.TrimSpace(t))
+	switch {
+	case strings.HasPrefix(lower, "varchar"):
+		return "varchar"
+	case lower == "integer":
+		return "int"
+	default:
+		return lower
+	}
+}
