+type inspectJSON struct {
+	Schemas []inspectJSONSchema `json:"schemas"`
+}
+
+type inspectJSONSchema struct {
+	Name   string             `json:"name"`
+	Tables []inspectJSONTable `json:"tables,omitempty"`
+}
+
+type inspectJSONTable struct {
+	Name       string               `json:"name"`
+	Columns    []inspectJSONColumn  `json:"columns,omitempty"`
+	PrimaryKey *inspectJSONPrimary  `json:"primary_key,omitempty"`
+}
+
+type inspectJSONColumn struct {
+	Name string `json:"name"`
+	Type string `json:"type"`
+}
+
+type inspectJSONPrimary struct {
+	Parts []inspectJSONPart `json:"parts"`
+}
+
+type inspectJSONPart struct {
+	Column string `json:"column"`
+}
+
+func inspectJSONFromState(st schemaState) inspectJSON {
+	out := inspectJSON{Schemas: []inspectJSONSchema{{Name: st.SchemaName}}}
+	for _, tbl := range st.Tables {
+		entry := inspectJSONTable{Name: tbl.Name}
+		for _, col := range tbl.Columns {
+			raw := col.RawType
+			if raw == "" {
+				raw = normalizeType(col.Type)
+				if raw == "int" {
+					raw = "INT"
+				}
+			}
+			entry.Columns = append(entry.Columns, inspectJSONColumn{Name: col.Name, Type: raw})
+		}
+		if len(tbl.PrimaryKey) > 0 {
+			entry.PrimaryKey = &inspectJSONPrimary{}
+			for _, name := range tbl.PrimaryKey {
+				entry.PrimaryKey.Parts = append(entry.PrimaryKey.Parts, inspectJSONPart{Column: name})
+			}
+		}
+		out.Schemas[0].Tables = append(out.Schemas[0].Tables, entry)
+	}
+	return out
+}
