package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"unicode"
)

type resourceRef struct {
	scheme string
	body   string
}

type schemaState struct {
	SchemaName string
	Tables     []tableDef
}

type tableDef struct {
	Name       string
	Columns    []columnDef
	PrimaryKey []string
}

type columnDef struct {
	Name    string
	Type    string
	RawType string
	NotNull bool
}

type schemaOp interface {
	Comment() string
	SQLCompact() string
	SQLPretty() string
}

type createTableOp struct {
	Table tableDef
}

func (o createTableOp) Comment() string   { return fmt.Sprintf("-- Create %q table", o.Table.Name) }
func (o createTableOp) SQLCompact() string { return renderCreateCompact(o.Table) }
func (o createTableOp) SQLPretty() string  { return renderCreatePretty(o.Table) }

type dropTableOp struct {
	Table tableDef
}

func (o dropTableOp) Comment() string   { return fmt.Sprintf("-- Drop %q table", o.Table.Name) }
func (o dropTableOp) SQLCompact() string { return fmt.Sprintf("DROP TABLE `%s`;", o.Table.Name) }
func (o dropTableOp) SQLPretty() string  { return fmt.Sprintf("DROP TABLE `%s`;", o.Table.Name) }

func diffStates(current, desired schemaState) []schemaOp {
	currentByName := map[string]tableDef{}
	desiredByName := map[string]tableDef{}
	for _, tbl := range current.Tables {
		currentByName[tbl.Name] = tbl
	}
	for _, tbl := range desired.Tables {
		desiredByName[tbl.Name] = tbl
	}
	var ops []schemaOp
	for _, tbl := range desired.Tables {
		cur, ok := currentByName[tbl.Name]
		if !ok {
			ops = append(ops, createTableOp{Table: tbl})
			continue
		}
		if !sameTable(cur, tbl) {
			ops = append(ops, dropTableOp{Table: cur}, createTableOp{Table: tbl})
		}
	}
	for _, tbl := range current.Tables {
		if _, ok := desiredByName[tbl.Name]; ok {
			continue
		}
		ops = append(ops, dropTableOp{Table: tbl})
	}
	return ops
}

func sameTable(a, b tableDef) bool {
	if a.Name != b.Name || len(a.Columns) != len(b.Columns) || len(a.PrimaryKey) != len(b.PrimaryKey) {
		return false
	}
	for i := range a.Columns {
		if a.Columns[i].Name != b.Columns[i].Name || normalizeType(a.Columns[i].Type) != normalizeType(b.Columns[i].Type) || a.Columns[i].NotNull != b.Columns[i].NotNull {
			return false
		}
	}
	for i := range a.PrimaryKey {
		if a.PrimaryKey[i] != b.PrimaryKey[i] {
			return false
		}
	}
	return true
}

func applyOperations(db *sqliteDB, ops []schemaOp) error {
	for _, op := range ops {
		if err := db.Exec(op.SQLCompact()); err != nil {
			return err
		}
	}
	return nil
}

func cleanSQLite(db *sqliteDB, tables []tableDef) error {
	if err := db.Exec("PRAGMA foreign_keys = off;"); err != nil {
		return err
	}
	for _, tbl := range tables {
		if err := db.Exec(fmt.Sprintf("DROP TABLE `%s`;", tbl.Name)); err != nil {
			return err
		}
	}
	return db.Exec("PRAGMA foreign_keys = on;")
}

func ensureSchemaMatch(actual string, st schemaState) error {
	if st.SchemaName == "" || st.SchemaName == actual {
		return nil
	}
	return fmt.Errorf("mismatched HCL and database schemas: %q <> %q", actual, st.SchemaName)
}

func loadStateWithSchema(raw string) (schemaState, string, error) {
	ref, err := parseResource(raw)
	if err != nil {
		return schemaState{}, "", err
	}
	switch ref.scheme {
	case "sqlite":
		db, foreignKeys, err := openSQLiteDB(ref.body)
		if err != nil {
			return schemaState{}, "", err
		}
		defer db.Close()
		if foreignKeys {
			if err := db.Exec("PRAGMA foreign_keys = on;"); err != nil {
				return schemaState{}, "", err
			}
		}
		st, err := inspectSQLite(db)
		return st, "main", err
	case "file":
		st, err := loadStateFromResources([]string{raw})
		return st, "", err
	default:
		return schemaState{}, "", fmt.Errorf("unsupported driver %q", ref.scheme)
	}
}

func loadStateFromResources(raws []string) (schemaState, error) {
	var combined schemaState
	for _, raw := range raws {
		ref, err := parseResource(raw)
		if err != nil {
			return schemaState{}, err
		}
		if ref.scheme != "file" {
			return schemaState{}, fmt.Errorf("unsupported driver %q", ref.scheme)
		}
		info, err := os.Stat(ref.body)
		if err != nil {
			return schemaState{}, err
		}
		if info.IsDir() {
			entries, err := os.ReadDir(ref.body)
			if err != nil {
				return schemaState{}, err
			}
			for _, entry := range entries {
				if entry.IsDir() || filepath.Ext(entry.Name()) != ".hcl" {
					continue
				}
				if err := mergeStateFile(&combined, filepath.Join(ref.body, entry.Name())); err != nil {
					return schemaState{}, err
				}
			}
			continue
		}
		if err := mergeStateFile(&combined, ref.body); err != nil {
			return schemaState{}, err
		}
	}
	if combined.SchemaName == "" {
		combined.SchemaName = "main"
	}
	return combined, nil
}

func mergeStateFile(dst *schemaState, path string) error {
	src, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	doc, err := parseDocument(path, string(src))
	if err != nil {
		return err
	}
	st, err := schemaStateFromDocument(doc)
	if err != nil {
		return err
	}
	if dst.SchemaName == "" && st.SchemaName != "" {
		dst.SchemaName = st.SchemaName
	}
	dst.Tables = append(dst.Tables, st.Tables...)
	return nil
}

func formatHCLPath(path string) (bool, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return false, err
	}
	formatted := formatHCL(string(src))
	if string(src) == formatted {
		return false, nil
	}
	info, err := os.Stat(path)
	if err != nil {
		return false, err
	}
	if err := os.WriteFile(path, []byte(formatted), info.Mode().Perm()); err != nil {
		return false, err
	}
	return true, nil
}

func formatHCL(src string) string {
	doc, err := parseDocument("", src)
	if err == nil {
		out := formatBody(doc, 0, true)
		if !strings.HasSuffix(out, "\n") {
			out += "\n"
		}
		return out
	}
	return formatLooseHCL(src)
}

type tokenKind int

const (
	tokenEOF tokenKind = iota
	tokenNewline
	tokenIdent
	tokenString
	tokenNumber
	tokenLBrace
	tokenRBrace
	tokenLBracket
	tokenRBracket
	tokenLParen
	tokenRParen
	tokenEqual
	tokenComma
	tokenDot
)

type token struct {
	kind tokenKind
	text string
	line int
	col  int
	end  int
}

type document struct {
	items []item
}

type item interface {
	isItem()
}

type blockItem struct {
	typ    string
	labels []label
	body   document
}

func (blockItem) isItem() {}

type attrItem struct {
	name string
	expr expr
}

func (attrItem) isItem() {}

type label struct {
	raw    string
	quoted bool
}

type expr interface {
	isExpr()
}

type identExpr struct{ name string }
type stringExpr struct{ raw string }
type numberExpr struct{ raw string }
type boolExpr struct{ value bool }
type traversalExpr struct{ parts []string }
type callExpr struct {
	name string
	args []expr
}
type listExpr struct{ elems []expr }

func (identExpr) isExpr()     {}
func (stringExpr) isExpr()    {}
func (numberExpr) isExpr()    {}
func (boolExpr) isExpr()      {}
func (traversalExpr) isExpr() {}
func (callExpr) isExpr()      {}
func (listExpr) isExpr()      {}

func parseDocument(path, src string) (document, error) {
	toks, err := lex(src)
	if err != nil {
		return document{}, err
	}
	p := &parser{path: path, toks: toks}
	doc, err := p.parseDocument(false)
	if err != nil {
		return document{}, err
	}
	return doc, nil
}

type parser struct {
	path string
	toks []token
	pos  int
}

func (p *parser) parseDocument(untilBrace bool) (document, error) {
	var items []item
	for {
		p.skipNewlines()
		tok := p.peek()
		if tok.kind == tokenEOF {
			if untilBrace {
				return document{}, p.errorAt(tok, "Argument or block definition required", "An argument or block definition is required here.")
			}
			return document{items: items}, nil
		}
		if tok.kind == tokenRBrace {
			if untilBrace {
				p.next()
				return document{items: items}, nil
			}
			return document{items: items}, nil
		}
		it, err := p.parseItem()
		if err != nil {
			return document{}, err
		}
		items = append(items, it)
		p.skipNewlines()
	}
}

func (p *parser) parseItem() (item, error) {
	first := p.peek()
	if first.kind != tokenIdent {
		return nil, p.errorAt(first, "Argument or block definition required", "An argument or block definition is required here.")
	}
	p.next()
	idents := []token{first}
	for p.peek().kind == tokenIdent {
		idents = append(idents, p.next())
	}
	if p.peek().kind == tokenEqual && len(idents) == 1 {
		p.next()
		ex, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		return attrItem{name: first.text, expr: ex}, nil
	}
	var labels []label
	for p.peek().kind == tokenString {
		labels = append(labels, label{raw: p.next().text, quoted: true})
	}
	if p.peek().kind != tokenLBrace || len(idents) != 1 {
		return nil, p.errorAt(p.peek(), "Argument or block definition required", "An argument or block definition is required here.")
	}
	p.next()
	body, err := p.parseDocument(true)
	if err != nil {
		return nil, err
	}
	return blockItem{typ: first.text, labels: labels, body: body}, nil
}

func (p *parser) parseExpr() (expr, error) {
	switch tok := p.peek(); tok.kind {
	case tokenString:
		p.next()
		return stringExpr{raw: tok.text}, nil
	case tokenNumber:
		p.next()
		return numberExpr{raw: tok.text}, nil
	case tokenIdent:
		p.next()
		if tok.text == "true" {
			return boolExpr{value: true}, nil
		}
		if tok.text == "false" {
			return boolExpr{value: false}, nil
		}
		if p.peek().kind == tokenLParen {
			p.next()
			var args []expr
			if p.peek().kind != tokenRParen {
				for {
					arg, err := p.parseExpr()
					if err != nil {
						return nil, err
					}
					args = append(args, arg)
					if p.peek().kind == tokenComma {
						p.next()
						continue
					}
					break
				}
			}
			if p.peek().kind != tokenRParen {
				return nil, p.errorAt(p.peek(), "Argument or block definition required", "An argument or block definition is required here.")
			}
			p.next()
			return callExpr{name: tok.text, args: args}, nil
		}
		parts := []string{tok.text}
		for p.peek().kind == tokenDot {
			p.next()
			next := p.peek()
			if next.kind != tokenIdent {
				return nil, p.errorAt(next, "Argument or block definition required", "An argument or block definition is required here.")
			}
			p.next()
			parts = append(parts, next.text)
		}
		if len(parts) == 1 {
			return identExpr{name: tok.text}, nil
		}
		return traversalExpr{parts: parts}, nil
	case tokenLBracket:
		p.next()
		var elems []expr
		if p.peek().kind != tokenRBracket {
			for {
				ex, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				elems = append(elems, ex)
				if p.peek().kind == tokenComma {
					p.next()
					continue
				}
				break
			}
		}
		if p.peek().kind != tokenRBracket {
			return nil, p.errorAt(p.peek(), "Argument or block definition required", "An argument or block definition is required here.")
		}
		p.next()
		return listExpr{elems: elems}, nil
	default:
		return nil, p.errorAt(tok, "Argument or block definition required", "An argument or block definition is required here.")
	}
}

func (p *parser) skipNewlines() {
	for p.peek().kind == tokenNewline {
		p.next()
	}
}

func (p *parser) peek() token {
	if p.pos >= len(p.toks) {
		return token{kind: tokenEOF}
	}
	return p.toks[p.pos]
}

func (p *parser) next() token {
	tok := p.peek()
	if p.pos < len(p.toks) {
		p.pos++
	}
	return tok
}

func (p *parser) errorAt(tok token, summary, detail string) error {
	line := tok.line
	col := tok.col
	end := tok.end
	if line == 0 {
		line = 1
		col = 1
		end = 1
	}
	path := p.path
	if path == "" {
		path = "<input>"
	}
	return fmt.Errorf("%s:%d,%d-%d: %s; %s", path, line, col, end, summary, detail)
}

func lex(src string) ([]token, error) {
	var toks []token
	line, col := 1, 1
	for i := 0; i < len(src); {
		ch := src[i]
		switch ch {
		case '\r':
			i++
		case '\n':
			toks = append(toks, token{kind: tokenNewline, text: "\n", line: line, col: col, end: col + 1})
			i++
			line++
			col = 1
		case ' ', '\t':
			i++
			col++
		case '#':
			for i < len(src) && src[i] != '\n' {
				i++
				col++
			}
		case '/':
			if i+1 < len(src) && src[i+1] == '/' {
				for i < len(src) && src[i] != '\n' {
					i++
					col++
				}
				continue
			}
			i++
			col++
		case '{':
			toks = append(toks, token{kind: tokenLBrace, text: "{", line: line, col: col, end: col + 1})
			i++
			col++
		case '}':
			toks = append(toks, token{kind: tokenRBrace, text: "}", line: line, col: col, end: col + 1})
			i++
			col++
		case '[':
			toks = append(toks, token{kind: tokenLBracket, text: "[", line: line, col: col, end: col + 1})
			i++
			col++
		case ']':
			toks = append(toks, token{kind: tokenRBracket, text: "]", line: line, col: col, end: col + 1})
			i++
			col++
		case '(':
			toks = append(toks, token{kind: tokenLParen, text: "(", line: line, col: col, end: col + 1})
			i++
			col++
		case ')':
			toks = append(toks, token{kind: tokenRParen, text: ")", line: line, col: col, end: col + 1})
			i++
			col++
		case '=':
			toks = append(toks, token{kind: tokenEqual, text: "=", line: line, col: col, end: col + 1})
			i++
			col++
		case ',':
			toks = append(toks, token{kind: tokenComma, text: ",", line: line, col: col, end: col + 1})
			i++
			col++
		case '.':
			toks = append(toks, token{kind: tokenDot, text: ".", line: line, col: col, end: col + 1})
			i++
			col++
		case '"':
			startLine, startCol := line, col
			j := i + 1
			for j < len(src) {
				if src[j] == '\\' && j+1 < len(src) {
					j += 2
					continue
				}
				if src[j] == '"' {
					j++
					break
				}
				if src[j] == '\n' {
					break
				}
				j++
			}
			raw := src[i:j]
			toks = append(toks, token{kind: tokenString, text: raw, line: startLine, col: startCol, end: startCol + len(raw)})
			col += len(raw)
			i = j
		default:
			if unicode.IsDigit(rune(ch)) {
				start := i
				startCol := col
				for i < len(src) && unicode.IsDigit(rune(src[i])) {
					i++
					col++
				}
				toks = append(toks, token{kind: tokenNumber, text: src[start:i], line: line, col: startCol, end: col})
				continue
			}
			if isIdentChar(ch) {
				start := i
				startCol := col
				for i < len(src) && isIdentChar(src[i]) {
					i++
					col++
				}
				toks = append(toks, token{kind: tokenIdent, text: src[start:i], line: line, col: startCol, end: col})
				continue
			}
			i++
			col++
		}
	}
	toks = append(toks, token{kind: tokenEOF, line: line, col: col, end: col})
	return toks, nil
}

func isIdentChar(b byte) bool {
	return unicode.IsLetter(rune(b)) || unicode.IsDigit(rune(b)) || b == '_' || b == '-'
}

func formatBody(doc document, indent int, topLevel bool) string {
	width := 0
	for _, it := range doc.items {
		if attr, ok := it.(attrItem); ok && len(attr.name) > width {
			width = len(attr.name)
		}
	}
	var lines []string
	for idx, it := range doc.items {
		if topLevel && idx > 0 {
			if _, ok := it.(blockItem); ok {
				if _, prev := doc.items[idx-1].(blockItem); prev {
					lines = append(lines, "")
				}
			}
		}
		switch v := it.(type) {
		case attrItem:
			pad := strings.Repeat(" ", width-len(v.name))
			lines = append(lines, strings.Repeat("  ", indent)+v.name+pad+" = "+formatExpr(v.expr))
		case blockItem:
			header := strings.Repeat("  ", indent) + v.typ
			for _, label := range v.labels {
				header += " " + label.raw
			}
			header += " {"
			lines = append(lines, header)
			body := formatBody(v.body, indent+1, false)
			if body != "" {
				lines = append(lines, strings.Split(body, "\n")...)
			}
			lines = append(lines, strings.Repeat("  ", indent)+"}")
		}
	}
	return strings.TrimSuffix(strings.Join(lines, "\n"), "\n")
}

func formatExpr(ex expr) string {
	switch v := ex.(type) {
	case identExpr:
		return v.name
	case stringExpr:
		return v.raw
	case numberExpr:
		return v.raw
	case boolExpr:
		if v.value {
			return "true"
		}
		return "false"
	case traversalExpr:
		return strings.Join(v.parts, ".")
	case callExpr:
		args := make([]string, len(v.args))
		for i, arg := range v.args {
			args[i] = formatExpr(arg)
		}
		return v.name + "(" + strings.Join(args, ", ") + ")"
	case listExpr:
		args := make([]string, len(v.elems))
		for i, arg := range v.elems {
			args[i] = formatExpr(arg)
		}
		return "[" + strings.Join(args, ", ") + "]"
	default:
		return ""
	}
}

func formatLooseHCL(src string) string {
	lines := strings.Split(strings.ReplaceAll(src, "\r\n", "\n"), "\n")
	indent := 0
	var out []string
	for _, raw := range lines {
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" {
			continue
		}
		toks := looseTokens(trimmed)
		if len(toks) == 0 {
			continue
		}
		leadingClosers := 0
		for leadingClosers < len(toks) && toks[leadingClosers] == "}" {
			leadingClosers++
		}
		if leadingClosers > 0 {
			indent -= leadingClosers
			if indent < 0 {
				indent = 0
			}
		}
		out = append(out, strings.Repeat("  ", indent)+joinLooseTokens(toks))
		opens, closes := 0, 0
		for _, tok := range toks {
			if tok == "{" {
				opens++
			}
			if tok == "}" {
				closes++
			}
		}
		indent += opens - (closes - leadingClosers)
	}
	return strings.Join(out, "\n") + "\n"
}

func looseTokens(line string) []string {
	var toks []string
	for i := 0; i < len(line); {
		switch line[i] {
		case ' ', '\t':
			i++
		case '"':
			j := i + 1
			for j < len(line) {
				if line[j] == '\\' && j+1 < len(line) {
					j += 2
					continue
				}
				if line[j] == '"' {
					j++
					break
				}
				j++
			}
			toks = append(toks, line[i:j])
			i = j
		case '{', '}', '[', ']', '(', ')', '=', ',', '.':
			toks = append(toks, string(line[i]))
			i++
		default:
			start := i
			for i < len(line) && !strings.ContainsRune(" \t{}[]()=,.", rune(line[i])) {
				i++
			}
			toks = append(toks, line[start:i])
		}
	}
	return toks
}

func joinLooseTokens(toks []string) string {
	var b strings.Builder
	last := ""
	for _, tok := range toks {
		switch tok {
		case "=":
			trimBuilderSpace(&b)
			b.WriteString(" = ")
		case ",":
			trimBuilderSpace(&b)
			b.WriteString(", ")
		case ".":
			trimBuilderSpace(&b)
			b.WriteString(".")
		case "(", "[":
			trimBuilderSpace(&b)
			b.WriteString(tok)
		case ")", "]":
			trimBuilderSpace(&b)
			b.WriteString(tok)
		case "{":
			if b.Len() > 0 && !strings.HasSuffix(b.String(), " ") {
				b.WriteByte(' ')
			}
			b.WriteString("{")
		case "}":
			trimBuilderSpace(&b)
			b.WriteString("}")
		default:
			if b.Len() > 0 && last != "." && last != "(" && last != "[" && !strings.HasSuffix(b.String(), " ") {
				b.WriteByte(' ')
			}
			b.WriteString(tok)
		}
		last = tok
	}
	return b.String()
}

func trimBuilderSpace(b *strings.Builder) {
	s := b.String()
	if strings.HasSuffix(s, " ") {
		_ = b
	}
}

type configEnv struct {
	URL     string
	DevURL  string
	Schemas []string
}

func resolveProjectEnv(cfg projectFlags) (configEnv, error) {
	if cfg.env == "" {
		return configEnv{}, nil
	}
	path, err := parseConfigPath(cfg.config)
	if err != nil {
		return configEnv{}, err
	}
	src, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return configEnv{}, fmt.Errorf("config file %q was not found: %w", path, err)
		}
		return configEnv{}, err
	}
	doc, err := parseDocument(path, string(src))
	if err != nil {
		return configEnv{}, err
	}
	return projectEnvFromDocument(doc, cfg.env, cfg.vars)
}

func parseConfigPath(spec string) (string, error) {
	idx := strings.Index(spec, "://")
	if idx < 0 {
		return "", fmt.Errorf("missing scheme for config file. Did you mean file://%s?", spec)
	}
	scheme := spec[:idx]
	if scheme != "file" {
		return "", fmt.Errorf("unsupported config file driver %q", scheme)
	}
	return spec[idx+3:], nil
}

type valueKind int

const (
	valueString valueKind = iota
	valueBool
	valueList
)

type value struct {
	kind valueKind
	s    string
	b    bool
	list []value
}

func projectEnvFromDocument(doc document, envName string, varsInput []string) (configEnv, error) {
	vars := map[string]value{}
	inputs := map[string]string{}
	for _, item := range varsInput {
		name, value, ok := strings.Cut(item, "=")
		if !ok || name == "" {
			return configEnv{}, fmt.Errorf("invalid variable assignment %q", item)
		}
		inputs[name] = value
	}
	var localsBlock []attrItem
	envs := map[string]blockItem{}
	for _, it := range doc.items {
		block, ok := it.(blockItem)
		if !ok {
			continue
		}
		switch block.typ {
		case "variable":
			if len(block.labels) == 0 {
				continue
			}
			name, _ := strconv.Unquote(block.labels[0].raw)
			if override, ok := inputs[name]; ok {
				vars[name] = value{kind: valueString, s: override}
				continue
			}
			for _, inner := range block.body.items {
				attr, ok := inner.(attrItem)
				if !ok || attr.name != "default" {
					continue
				}
				val, err := evalExpr(attr.expr, evalContext{vars: vars, locals: map[string]value{}, atlasEnv: envName})
				if err != nil {
					return configEnv{}, err
				}
				vars[name] = val
			}
			if _, ok := vars[name]; !ok {
				vars[name] = value{kind: valueString, s: ""}
			}
		case "locals":
			for _, inner := range block.body.items {
				if attr, ok := inner.(attrItem); ok {
					localsBlock = append(localsBlock, attr)
				}
			}
		case "env":
			if len(block.labels) == 0 {
				continue
			}
			name, _ := strconv.Unquote(block.labels[0].raw)
			envs[name] = block
		}
	}
	for name, override := range inputs {
		if _, ok := vars[name]; !ok {
			vars[name] = value{kind: valueString, s: override}
		}
	}
	locals := map[string]value{}
	pending := append([]attrItem{}, localsBlock...)
	for len(pending) > 0 {
		progress := false
		var next []attrItem
		for _, attr := range pending {
			val, err := evalExpr(attr.expr, evalContext{vars: vars, locals: locals, atlasEnv: envName})
			if err != nil {
				next = append(next, attr)
				continue
			}
			locals[attr.name] = val
			progress = true
		}
		if !progress {
			break
		}
		pending = next
	}
	block, ok := envs[envName]
	if !ok {
		return configEnv{}, fmt.Errorf("env %q not defined in config file", envName)
	}
	ctx := evalContext{vars: vars, locals: locals, atlasEnv: envName}
	var out configEnv
	for _, inner := range block.body.items {
		attr, ok := inner.(attrItem)
		if !ok {
			continue
		}
		val, err := evalExpr(attr.expr, ctx)
		if err != nil {
			return configEnv{}, err
		}
		switch attr.name {
		case "url":
			out.URL = val.s
		case "dev":
			out.DevURL = val.s
		case "schemas":
			for _, item := range val.list {
				out.Schemas = append(out.Schemas, item.s)
			}
		}
	}
	return out, nil
}

type evalContext struct {
	vars     map[string]value
	locals   map[string]value
	atlasEnv string
}

func evalExpr(ex expr, ctx evalContext) (value, error) {
	switch v := ex.(type) {
	case stringExpr:
		s, err := strconv.Unquote(v.raw)
		if err != nil {
			return value{}, err
		}
		for {
			start := strings.Index(s, "${")
			if start < 0 {
				break
			}
			end := strings.Index(s[start+2:], "}")
			if end < 0 {
				break
			}
			end += start + 2
			inner, err := parseInlineExpr(s[start+2 : end])
			if err != nil {
				return value{}, err
			}
			val, err := evalExpr(inner, ctx)
			if err != nil {
				return value{}, err
			}
			s = s[:start] + val.s + s[end+1:]
		}
		return value{kind: valueString, s: s}, nil
	case numberExpr:
		return value{kind: valueString, s: v.raw}, nil
	case boolExpr:
		return value{kind: valueBool, b: v.value}, nil
	case identExpr:
		return value{kind: valueString, s: v.name}, nil
	case traversalExpr:
		if len(v.parts) == 0 {
			return value{}, fmt.Errorf("invalid traversal")
		}
		switch v.parts[0] {
		case "var":
			if len(v.parts) == 2 {
				return ctx.vars[v.parts[1]], nil
			}
		case "local":
			if len(v.parts) == 2 {
				return ctx.locals[v.parts[1]], nil
			}
		case "atlas":
			if len(v.parts) == 2 && v.parts[1] == "env" {
				return value{kind: valueString, s: ctx.atlasEnv}, nil
			}
		}
		return value{}, fmt.Errorf("unknown symbol")
	case callExpr:
		if v.name == "getenv" && len(v.args) == 1 {
			arg, err := evalExpr(v.args[0], ctx)
			if err != nil {
				return value{}, err
			}
			return value{kind: valueString, s: os.Getenv(arg.s)}, nil
		}
		return value{}, fmt.Errorf("unsupported call")
	case listExpr:
		var out []value
		for _, elem := range v.elems {
			val, err := evalExpr(elem, ctx)
			if err != nil {
				return value{}, err
			}
			out = append(out, val)
		}
		return value{kind: valueList, list: out}, nil
	default:
		return value{}, fmt.Errorf("unsupported expression")
	}
}

func parseInlineExpr(text string) (expr, error) {
	doc, err := parseDocument("", "x = "+text+"\n")
	if err != nil {
		return nil, err
	}
	if len(doc.items) == 0 {
		return nil, fmt.Errorf("empty expression")
	}
	attr, ok := doc.items[0].(attrItem)
	if !ok {
		return nil, fmt.Errorf("invalid expression")
	}
	return attr.expr, nil
}

func schemaStateFromDocument(doc document) (schemaState, error) {
	var st schemaState
	for _, it := range doc.items {
		block, ok := it.(blockItem)
		if !ok {
			continue
		}
		switch block.typ {
		case "schema":
			if len(block.labels) > 0 && st.SchemaName == "" {
				name, _ := strconv.Unquote(block.labels[0].raw)
				st.SchemaName = name
			}
		case "table":
			tbl, schemaName, err := tableFromBlock(block)
			if err != nil {
				return schemaState{}, err
			}
			if st.SchemaName == "" {
				st.SchemaName = schemaName
			}
			st.Tables = append(st.Tables, tbl)
		}
	}
	return st, nil
}

func tableFromBlock(block blockItem) (tableDef, string, error) {
	if len(block.labels) == 0 {
		return tableDef{}, "", fmt.Errorf("table block missing name")
	}
	name, _ := strconv.Unquote(block.labels[0].raw)
	tbl := tableDef{Name: name}
	schemaName := "main"
	for _, it := range block.body.items {
		switch inner := it.(type) {
		case attrItem:
			if inner.name == "schema" {
				switch ex := inner.expr.(type) {
				case traversalExpr:
					if len(ex.parts) == 2 && ex.parts[0] == "schema" {
						schemaName = ex.parts[1]
					}
				}
			}
		case blockItem:
			switch inner.typ {
			case "column":
				col, err := columnFromBlock(inner)
				if err != nil {
					return tableDef{}, "", err
				}
				tbl.Columns = append(tbl.Columns, col)
			case "primary_key":
				for _, pkItem := range inner.body.items {
					attr, ok := pkItem.(attrItem)
					if !ok || attr.name != "columns" {
						continue
					}
					list, ok := attr.expr.(listExpr)
					if !ok {
						continue
					}
					for _, elem := range list.elems {
						if trav, ok := elem.(traversalExpr); ok && len(trav.parts) == 2 {
							tbl.PrimaryKey = append(tbl.PrimaryKey, trav.parts[1])
						}
					}
				}
			}
		}
	}
	return tbl, schemaName, nil
}

func columnFromBlock(block blockItem) (columnDef, error) {
	if len(block.labels) == 0 {
		return columnDef{}, fmt.Errorf("column block missing name")
	}
	name, _ := strconv.Unquote(block.labels[0].raw)
	col := columnDef{Name: name, NotNull: true}
	for _, it := range block.body.items {
		attr, ok := it.(attrItem)
		if !ok {
			continue
		}
		switch attr.name {
		case "type":
			col.Type = formatExpr(attr.expr)
		case "null":
			if ex, ok := attr.expr.(boolExpr); ok {
				col.NotNull = !ex.value
			}
		}
	}
	return col, nil
}

