package main

/*
#cgo LDFLAGS: -lsqlite3
#include <stdlib.h>
typedef struct sqlite3 sqlite3;
typedef struct sqlite3_stmt sqlite3_stmt;
int sqlite3_open(const char *filename, sqlite3 **ppDb);
int sqlite3_close(sqlite3*);
const char *sqlite3_errmsg(sqlite3*);
int sqlite3_exec(sqlite3*, const char *sql, int (*callback)(void*,int,char**,char**), void *, char **errmsg);
void sqlite3_free(void*);
int sqlite3_prepare_v2(sqlite3*, const char *zSql, int nByte, sqlite3_stmt **ppStmt, const char **pzTail);
int sqlite3_step(sqlite3_stmt*);
int sqlite3_finalize(sqlite3_stmt*);
int sqlite3_column_int(sqlite3_stmt*, int iCol);
const unsigned char *sqlite3_column_text(sqlite3_stmt*, int iCol);
*/
import "C"

import (
	"fmt"
	"net/url"
	"sort"
	"strings"
	"unsafe"
)

const (
	sqliteOK   = 0
	sqliteRow  = 100
	sqliteDone = 101
)

type sqliteDB struct {
	ptr *C.sqlite3
}

type sqliteStmt struct {
	db  *sqliteDB
	ptr *C.sqlite3_stmt
}

func openSQLiteDB(body string) (*sqliteDB, bool, error) {
	path, query, _ := strings.Cut(body, "?")
	if strings.HasPrefix(path, "file:") {
		path = strings.TrimPrefix(path, "file:")
	}
	values, _ := url.ParseQuery(query)
	filename := path
	if values.Get("mode") == "memory" {
		filename = ":memory:"
	}
	cname := C.CString(filename)
	defer C.free(unsafe.Pointer(cname))
	var raw *C.sqlite3
	if rc := C.sqlite3_open(cname, &raw); rc != sqliteOK {
		db := &sqliteDB{ptr: raw}
		err := db.err()
		_ = db.Close()
		return nil, false, err
	}
	return &sqliteDB{ptr: raw}, values.Get("_fk") == "1", nil
}

func (db *sqliteDB) Close() error {
	if db == nil || db.ptr == nil {
		return nil
	}
	if rc := C.sqlite3_close(db.ptr); rc != sqliteOK {
		return db.err()
	}
	db.ptr = nil
	return nil
}

func (db *sqliteDB) Exec(query string) error {
	cquery := C.CString(query)
	defer C.free(unsafe.Pointer(cquery))
	var errMsg *C.char
	if rc := C.sqlite3_exec(db.ptr, cquery, nil, nil, &errMsg); rc != sqliteOK {
		defer C.sqlite3_free(unsafe.Pointer(errMsg))
		return fmt.Errorf("%s", C.GoString(errMsg))
	}
	return nil
}

func (db *sqliteDB) Prepare(query string) (*sqliteStmt, error) {
	cquery := C.CString(query)
	defer C.free(unsafe.Pointer(cquery))
	var stmt *C.sqlite3_stmt
	if rc := C.sqlite3_prepare_v2(db.ptr, cquery, -1, &stmt, nil); rc != sqliteOK {
		return nil, db.err()
	}
	return &sqliteStmt{db: db, ptr: stmt}, nil
}

func (db *sqliteDB) err() error {
	return fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db.ptr)))
}

func (s *sqliteStmt) Finalize() {
	if s != nil && s.ptr != nil {
		C.sqlite3_finalize(s.ptr)
		s.ptr = nil
	}
}

func (s *sqliteStmt) Step() (bool, error) {
	rc := C.sqlite3_step(s.ptr)
	switch rc {
	case sqliteRow:
		return true, nil
	case sqliteDone:
		return false, nil
	default:
		return false, s.db.err()
	}
}

func (s *sqliteStmt) Text(col int) string {
	ptr := C.sqlite3_column_text(s.ptr, C.int(col))
	if ptr == nil {
		return ""
	}
	return C.GoString((*C.char)(unsafe.Pointer(ptr)))
}

func (s *sqliteStmt) Int(col int) int {
	return int(C.sqlite3_column_int(s.ptr, C.int(col)))
}

func inspectSQLite(db *sqliteDB) (schemaState, error) {
	stmt, err := db.Prepare(`SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY rowid`)
	if err != nil {
		return schemaState{}, err
	}
	defer stmt.Finalize()
	st := schemaState{SchemaName: "main"}
	for {
		ok, err := stmt.Step()
		if err != nil {
			return schemaState{}, err
		}
		if !ok {
			break
		}
		name := stmt.Text(0)
		tbl, err := inspectSQLiteTable(db, name)
		if err != nil {
			return schemaState{}, err
		}
		st.Tables = append(st.Tables, tbl)
	}
	return st, nil
}

func inspectSQLiteTable(db *sqliteDB, name string) (tableDef, error) {
	stmt, err := db.Prepare(fmt.Sprintf("PRAGMA table_info(`%s`)", strings.ReplaceAll(name, "`", "``")))
	if err != nil {
		return tableDef{}, err
	}
	defer stmt.Finalize()
	tbl := tableDef{Name: name}
	type pkPart struct {
		pos  int
		name string
	}
	var pk []pkPart
	for {
		ok, err := stmt.Step()
		if err != nil {
			return tableDef{}, err
		}
		if !ok {
			break
		}
		columnName := stmt.Text(1)
		typeName := stmt.Text(2)
		notNull := stmt.Int(3)
		pkPos := stmt.Int(5)
		tbl.Columns = append(tbl.Columns, columnDef{
			Name:    columnName,
			Type:    normalizeType(typeName),
			RawType: typeName,
			NotNull: notNull != 0 || pkPos > 0,
		})
		if pkPos > 0 {
			pk = append(pk, pkPart{pos: pkPos, name: columnName})
		}
	}
	sort.Slice(pk, func(i, j int) bool { return pk[i].pos < pk[j].pos })
	for _, part := range pk {
		tbl.PrimaryKey = append(tbl.PrimaryKey, part.name)
	}
	return tbl, nil
}

/workspace/config.go.content:
package main

import (
	"fmt"
	"os"
	"sort"
	"strings"

	"github.com/hashicorp/hcl/v2"
	"github.com/hashicorp/hcl/v2/hclparse"
	"github.com/hashicorp/hcl/v2/hclsyntax"
	"github.com/zclconf/go-cty/cty"
	_jsii "github.com/zclconf/go-cty/cty/function"
)

type projectEnv struct {
	URL     string
	DevURL  string
	Schemas []string
}

func resolveProjectEnv(cfg *configFlags) (projectEnv, error) {
	if cfg == nil || cfg.Env == "" {
		return projectEnv{}, nil
	}

	path, err := parseConfigPath(cfg.Config)
	if err != nil {
		return projectEnv{}, err
	}
	src, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return projectEnv{}, fmt.Errorf("config file %q was not found: %w", path, err)
		}
		return projectEnv{}, err
	}

	parser := hclparse.NewParser()
	file, diags := parser.ParseHCL(src, path)
	if diags.HasErrors() {
		return projectEnv{}, fmt.Errorf(diags.Error())
	}

	body, ok := file.Body.(*hclsyntax.Body)
	if !ok {
		return projectEnv{}, fmt.Errorf("unsupported config body")
	}

	vars, err := evaluateVariables(body, cfg.Vars)
	if err != nil {
		return projectEnv{}, err
	}

	locals, err := evaluateLocals(body, cfg.Env, vars)
	if err != nil {
		return projectEnv{}, err
	}

	env, ok := findEnv(body, cfg.Env, vars, locals)
	if !ok {
		return projectEnv{}, fmt.Errorf("env %q not defined in config file", cfg.Env)
	}
	return env, nil
}

func parseConfigPath(spec string) (string, error) {
	idx := strings.Index(spec, "://")
	if idx < 0 {
		return "", fmt.Errorf("missing scheme for config file. Did you mean file://%s?", spec)
	}
	scheme, rest := spec[:idx], spec[idx+3:]
	if scheme != "file" {
		return "", fmt.Errorf("unsupported config file driver %q", scheme)
	}
	return rest, nil
}

func evaluateVariables(body *hclsyntax.Body, inputs []string) (map[string]cty.Value, error) {
	overrides := map[string]string{}
	for _, item := range inputs {
		name, value, ok := strings.Cut(item, "=")
		if !ok || name == "" {
			return nil, fmt.Errorf("invalid variable assignment %q", item)
		}
		overrides[name] = value
	}

	vars := map[string]cty.Value{}
	for _, block := range body.Blocks {
		if block.Type != "variable" || len(block.Labels) == 0 {
			continue
		}
		name := block.Labels[0]
		if override, ok := overrides[name]; ok {
			vars[name] = cty.StringVal(override)
			continue
		}
		attr, ok := block.Body.Attributes["default"]
		if !ok {
			vars[name] = cty.StringVal("")
			continue
		}
		val, diags := attr.Expr.Value(&hcl.EvalContext{})
		if diags.HasErrors() {
			return nil, fmt.Errorf(diags.Error())
		}
		vars[name] = val
	}
	for name, value := range overrides {
		if _, ok := vars[name]; !ok {
			vars[name] = cty.StringVal(value)
		}
	}
	return vars, nil
}

func evaluateLocals(body *hclsyntax.Body, envName string, vars map[string]cty.Value) (map[string]cty.Value, error) {
	localAttrs := map[string]*hclsyntax.Attribute{}
	for _, block := range body.Blocks {
		if block.Type != "locals" {
			continue
		}
		for name, attr := range block.Body.Attributes {
			localAttrs[name] = attr
		}
	}

	locals := map[string]cty.Value{}
	if len(localAttrs) == 0 {
		return locals, nil
	}

	keys := make([]string, 0, len(localAttrs))
	for name := range localAttrs {
		keys = append(keys, name)
	}
	sort.Strings(keys)

	pending := map[string]*hclsyntax.Attribute{}
	for _, name := range keys {
		pending[name] = localAttrs[name]
	}

	for len(pending) > 0 {
		progress := false
		for _, name := range keys {
			attr, ok := pending[name]
			if !ok {
				continue
			}
			ctx := newEvalContext(envName, vars, locals)
			val, diags := attr.Expr.Value(ctx)
			if diags.HasErrors() {
				continue
			}
			locals[name] = val
			delete(pending, name)
			progress = true
		}
		if progress {
			continue
		}
		for _, name := range keys {
			attr, ok := pending[name]
			if !ok {
				continue
			}
			_, diags := attr.Expr.Value(newEvalContext(envName, vars, locals))
			if diags.HasErrors() {
				return nil, fmt.Errorf(diags.Error())
			}
		}
		break
	}

	return locals, nil
}

func findEnv(body *hclsyntax.Body, envName string, vars, locals map[string]cty.Value) (projectEnv, bool) {
	for _, block := range body.Blocks {
		if block.Type != "env" || len(block.Labels) == 0 || block.Labels[0] != envName {
			continue
		}
		ctx := newEvalContext(envName, vars, locals)
		env := projectEnv{}
		if attr, ok := block.Body.Attributes["url"]; ok {
			val, diags := attr.Expr.Value(ctx)
			if diags.HasErrors() {
				return projectEnv{}, false
			}
			env.URL = ctyToString(val)
		}
		if attr, ok := block.Body.Attributes["dev"]; ok {
			val, diags := attr.Expr.Value(ctx)
			if diags.HasErrors() {
				return projectEnv{}, false
			}
			env.DevURL = ctyToString(val)
		}
		if attr, ok := block.Body.Attributes["schemas"]; ok {
			val, diags := attr.Expr.Value(ctx)
			if diags.HasErrors() {
				return projectEnv{}, false
			}
			if val.Type().IsTupleType() || val.Type().IsListType() || val.Type().IsSetType() {
				it := val.ElementIterator()
				for it.Next() {
					_, item := it.Element()
					env.Schemas = append(env.Schemas, ctyToString(item))
				}
			}
		}
		return env, true
	}
	return projectEnv{}, false
}

func newEvalContext(envName string, vars, locals map[string]cty.Value) *hcl.EvalContext {
	varObj := cty.ObjectVal(map[string]cty.Value{})
	if len(vars) > 0 {
		varObj = cty.ObjectVal(vars)
	}
	localObj := cty.ObjectVal(map[string]cty.Value{})
	if len(locals) > 0 {
		localObj = cty.ObjectVal(locals)
	}
	return &hcl.EvalContext{
		Variables: map[string]cty.Value{
			"var":   varObj,
			"local": localObj,
			"atlas": cty.ObjectVal(map[string]cty.Value{
				"env": cty.StringVal(envName),
			}),
		},
		Functions: map[string]function{
			"getenv": newGetenvFunc(),
		},
	}
}

type function = *_jsii.Function

func newGetenvFunc() function {
	return _jsii.New(&_jsii.Spec{
		Params: []_jsii.Parameter{
			{Name: "name", Type: cty.String},
		},
		Type: _jsii.StaticReturnType(cty.String),
		Impl: func(args []cty.Value, retType cty.Type) (cty.Value, error) {
			return cty.StringVal(os.Getenv(args[0].AsString())), nil
		},
	})
}

func ctyToString(v cty.Value) string {
	if !v.IsKnown() || v.IsNull() {
		return ""
	}
	switch {
	case v.Type() == cty.String:
		return v.AsString()
	case v.Type() == cty.Number:
		bf := v.AsBigFloat()
		return bf.Text('f', -1)
	case v.Type() == cty.Bool:
		if v.True() {
			return "true"
		}
		return "false"
	default:
		return v.GoString()
	}
}

/workspace/schema.go.content:
package main

import (
	"bufio"
	"bytes"
	"database/sql"
	"encoding/json"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"text/template"

	_ "modernc.org/sqlite"

	"github.com/hashicorp/hcl/v2/hclsyntax"
	"github.com/hashicorp/hcl/v2/hclwrite"
	"github.com/spf13/cobra"
)

type state struct {
	SchemaName string
	Tables     []table
}

type table struct {
	Name       string
	Columns    []column
	PrimaryKey []string
}

type column struct {
	Name    string
	Type    string
	RawType string
	NotNull bool
}

type operationKind string

const (
	opCreate operationKind = "create"
	opDrop   operationKind = "drop"
)

type operation struct {
	Kind  operationKind
	Table table
}

type resourceRef struct {
	Scheme string
	Body   string
}

func runSchemaFmt(cmd *cobra.Command, args []string) error {
	if len(args) == 0 {
		args = []string{"."}
	}
	for _, arg := range args {
		info, err := os.Stat(arg)
		if err != nil {
			return err
		}
		if info.IsDir() {
			entries, err := os.ReadDir(arg)
			if err != nil {
				return err
			}
			for _, entry := range entries {
				if entry.IsDir() || filepath.Ext(entry.Name()) != ".hcl" {
					continue
				}
				path := filepath.Join(arg, entry.Name())
				changed, err := formatHCLFile(path)
				if err != nil {
					return err
				}
				if changed {
					fmt.Fprintln(cmd.OutOrStdout(), path)
				}
			}
			continue
		}
		if filepath.Ext(arg) != ".hcl" {
			continue
		}
		changed, err := formatHCLFile(arg)
		if err != nil {
			return err
		}
		if changed {
			fmt.Fprintln(cmd.OutOrStdout(), arg)
		}
	}
	return nil
}

func formatHCLFile(path string) (bool, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return false, err
	}
	formatted := hclwrite.Format(src)
	if bytes.Equal(src, formatted) {
		return false, nil
	}
	if err := os.WriteFile(path, formatted, 0o644); err != nil {
		return false, err
	}
	return true, nil
}

func runSchemaInspect(cmd *cobra.Command, cfg *configFlags, opts inspectOptions) error {
	env, err := resolveProjectEnv(cfg)
	if err != nil {
		return err
	}
	if opts.URL == "" {
		opts.URL = env.URL
	}
	if opts.DevURL == "" {
		opts.DevURL = env.DevURL
	}
	if len(opts.Schemas) == 0 && len(env.Schemas) > 0 {
		opts.Schemas = append(opts.Schemas, env.Schemas...)
	}
	if opts.URL == "" {
		return requiredFlagsError("url")
	}

	ref, err := parseResource(opts.URL)
	if err != nil {
		return err
	}

	switch ref.Scheme {
	case "sqlite":
		db, foreignKeys, err := openSQLite(ref.Body)
		if err != nil {
			return err
		}
		defer db.Close()
		if foreignKeys {
			if _, err := db.Exec(`PRAGMA foreign_keys = on`); err != nil {
				return err
			}
		}
		st, err := inspectSQLite(db)
		if err != nil {
			return err
		}
		out, err := renderState(st, opts.Format)
		if err != nil {
			return err
		}
		fmt.Fprint(cmd.OutOrStdout(), out)
		return nil
	default:
		return fmt.Errorf("unsupported driver %q", ref.Scheme)
	}
}

func runSchemaApply(cmd *cobra.Command, cfg *configFlags, opts applyOptions) error {
	env, err := resolveProjectEnv(cfg)
	if err != nil {
		return err
	}
	if opts.URL == "" {
		opts.URL = env.URL
	}
	if opts.DevURL == "" {
		opts.DevURL = env.DevURL
	}
	if len(opts.Schemas) == 0 && len(env.Schemas) > 0 {
		opts.Schemas = append(opts.Schemas, env.Schemas...)
	}
	if opts.URL == "" {
		return requiredFlagsError("url")
	}
	if len(opts.To) == 0 {
		return requiredFlagsError("to")
	}

	targetRef, err := parseResource(opts.URL)
	if err != nil {
		return err
	}
	if targetRef.Scheme != "sqlite" {
		return fmt.Errorf("unsupported driver %q", targetRef.Scheme)
	}

	desired, err := loadStateFromResources(opts.To)
	if err != nil {
		return err
	}
	if err := ensureSchemaMatch("main", desired); err != nil {
		return err
	}

	db, foreignKeys, err := openSQLite(targetRef.Body)
	if err != nil {
		return err
	}
	defer db.Close()
	if foreignKeys {
		if _, err := db.Exec(`PRAGMA foreign_keys = on`); err != nil {
			return err
		}
	}
	current, err := inspectSQLite(db)
	if err != nil {
		return err
	}

	ops := diffStates(current, desired)
	if len(ops) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "Schema is synced, no changes to be made")
		return nil
	}

	fmt.Fprint(cmd.OutOrStdout(), renderPlanPretty(ops))
	if opts.DryRun {
		return nil
	}
	if !opts.AutoApprove {
		ok, err := confirmApply()
		if err != nil {
			return err
		}
		if !ok {
			return nil
		}
	}
	return applyOperations(db, ops)
}

func runSchemaDiff(cmd *cobra.Command, cfg *configFlags, opts diffOptions) error {
	_, err := resolveProjectEnv(cfg)
	if err != nil {
		return err
	}
	if len(opts.From) == 0 {
		return requiredFlagsError("from")
	}
	if len(opts.To) == 0 {
		return requiredFlagsError("to")
	}

	fromState, fromSchema, err := loadStateWithSchema(opts.From[0])
	if err != nil {
		return err
	}
	toState, err := loadStateFromResources(opts.To)
	if err != nil {
		return err
	}
	if fromSchema == "main" {
		if err := ensureSchemaMatch(fromSchema, toState); err != nil {
			return err
		}
	}

	ops := diffStates(fromState, toState)
	if len(ops) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "Schemas are synced, no changes to be made.")
		return nil
	}
	fmt.Fprint(cmd.OutOrStdout(), renderPlanCompact(ops))
	return nil
}

func runSchemaClean(cmd *cobra.Command, cfg *configFlags, opts cleanOptions) error {
	env, err := resolveProjectEnv(cfg)
	if err != nil {
		return err
	}
	if opts.URL == "" {
		opts.URL = env.URL
	}
	if opts.URL == "" {
		return requiredFlagsError("url")
	}
	if opts.DryRun {
		return &verbatimError{msg: "Abort: 'atlas schema clean --dry-run' is not supported by the community version.\n\nTo install the non-community version of Atlas, use the following command:\n\n\tcurl -sSf https://atlasgo.sh | sh\n\nOr, visit the website to see all installation options:\n\n\thttps://atlasgo.io/docs#installation"}
	}

	ref, err := parseResource(opts.URL)
	if err != nil {
		return err
	}
	if ref.Scheme != "sqlite" {
		return fmt.Errorf("unsupported driver %q", ref.Scheme)
	}

	db, foreignKeys, err := openSQLite(ref.Body)
	if err != nil {
		return err
	}
	defer db.Close()
	if foreignKeys {
		if _, err := db.Exec(`PRAGMA foreign_keys = on`); err != nil {
			return err
		}
	}
	current, err := inspectSQLite(db)
	if err != nil {
		return err
	}
	if len(current.Tables) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "Nothing to drop")
		return nil
	}
	fmt.Fprint(cmd.OutOrStdout(), renderCleanPlan(current.Tables))
	if !opts.AutoApprove {
		ok, err := confirmApply()
		if err != nil {
			return err
		}
		if !ok {
			return nil
		}
	}
	return cleanSQLite(db, current.Tables)
}

func requiredFlagsError(names ...string) error {
	quoted := make([]string, len(names))
	for i, name := range names {
		quoted[i] = fmt.Sprintf("%q", name)
	}
	return fmt.Errorf("required flag(s) %s not set", strings.Join(quoted, ", "))
}

func parseResource(raw string) (resourceRef, error) {
	idx := strings.Index(raw, "://")
	if idx < 0 {
		return resourceRef{}, fmt.Errorf("missing scheme. See: https://atlasgo.io/url")
	}
	return resourceRef{Scheme: raw[:idx], Body: raw[idx+3:]}, nil
}

func openSQLite(body string) (*sql.DB, bool, error) {
	path, query, _ := strings.Cut(body, "?")
	values, _ := url.ParseQuery(query)

	dsn := "file:" + path
	if strings.HasPrefix(path, "file:") {
		dsn = path
	}
	if values.Get("mode") == "memory" && !strings.Contains(dsn, "?mode=memory") {
		dsn = dsn + "?mode=memory"
	}

	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, false, err
	}
	return db, values.Get("_fk") == "1", nil
}

func inspectSQLite(db *sql.DB) (state, error) {
	rows, err := db.Query(`SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY rowid`)
	if err != nil {
		return state{}, err
	}
	defer rows.Close()

	st := state{SchemaName: "main"}
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			return state{}, err
		}
		tbl, err := inspectSQLiteTable(db, name)
		if err != nil {
			return state{}, err
		}
		st.Tables = append(st.Tables, tbl)
	}
	return st, rows.Err()
}

func inspectSQLiteTable(db *sql.DB, name string) (table, error) {
	query := fmt.Sprintf("PRAGMA table_info(`%s`)", strings.ReplaceAll(name, "`", "``"))
	rows, err := db.Query(query)
	if err != nil {
		return table{}, err
	}
	defer rows.Close()

	tbl := table{Name: name}
	type pkPart struct {
		pos  int
		name string
	}
	var pk []pkPart
	for rows.Next() {
		var cid int
		var columnName, typeName string
		var notNull int
		var defaultValue sql.NullString
		var pkPos int
		if err := rows.Scan(&cid, &columnName, &typeName, &notNull, &defaultValue, &pkPos); err != nil {
			return table{}, err
		}
		tbl.Columns = append(tbl.Columns, column{
			Name:    columnName,
			Type:    normalizeType(typeName),
			RawType: typeName,
			NotNull: notNull != 0 || pkPos > 0,
		})
		if pkPos > 0 {
			pk = append(pk, pkPart{pos: pkPos, name: columnName})
		}
	}
	sort.Slice(pk, func(i, j int) bool { return pk[i].pos < pk[j].pos })
	for _, part := range pk {
		tbl.PrimaryKey = append(tbl.PrimaryKey, part.name)
	}
	return tbl, rows.Err()
}

func loadStateWithSchema(raw string) (state, string, error) {
	ref, err := parseResource(raw)
	if err != nil {
		return state{}, "", err
	}
	switch ref.Scheme {
	case "sqlite":
		db, foreignKeys, err := openSQLite(ref.Body)
		if err != nil {
			return state{}, "", err
		}
		defer db.Close()
		if foreignKeys {
			if _, err := db.Exec(`PRAGMA foreign_keys = on`); err != nil {
				return state{}, "", err
			}
		}
		st, err := inspectSQLite(db)
		return st, "main", err
	case "file":
		st, err := loadStateFromResources([]string{raw})
		return st, "", err
	default:
		return state{}, "", fmt.Errorf("unsupported driver %q", ref.Scheme)
	}
}

func loadStateFromResources(raws []string) (state, error) {
	combined := state{}
	for _, raw := range raws {
		ref, err := parseResource(raw)
		if err != nil {
			return state{}, err
		}
		if ref.Scheme != "file" {
			return state{}, fmt.Errorf("unsupported driver %q", ref.Scheme)
		}
		info, err := os.Stat(ref.Body)
		if err != nil {
			return state{}, err
		}
		if info.IsDir() {
			entries, err := os.ReadDir(ref.Body)
			if err != nil {
				return state{}, err
			}
			for _, entry := range entries {
				if entry.IsDir() || filepath.Ext(entry.Name()) != ".hcl" {
					continue
				}
				if err := mergeStateFile(&combined, filepath.Join(ref.Body, entry.Name())); err != nil {
					return state{}, err
				}
			}
			continue
		}
		if err := mergeStateFile(&combined, ref.Body); err != nil {
			return state{}, err
		}
	}
	if combined.SchemaName == "" {
		combined.SchemaName = "main"
	}
	return combined, nil
}

func mergeStateFile(dst *state, path string) error {
	src, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	file, diags := hclsyntax.ParseConfig(src, path, hclsyntax.Pos{Line: 1, Column: 1})
	if diags.HasErrors() {
		return fmt.Errorf(diags.Error())
	}
	body, ok := file.Body.(*hclsyntax.Body)
	if !ok {
		return fmt.Errorf("unsupported schema body")
	}
	parsed, err := parseSchemaBody(body)
	if err != nil {
		return err
	}
	if dst.SchemaName == "" {
		dst.SchemaName = parsed.SchemaName
	}
	if parsed.SchemaName != "" && dst.SchemaName == "" {
		dst.SchemaName = parsed.SchemaName
	}
	if parsed.SchemaName != "" && dst.SchemaName == "" {
		dst.SchemaName = parsed.SchemaName
	}
	if parsed.SchemaName != "" && dst.SchemaName == "" {
		dst.SchemaName = parsed.SchemaName
	}
	if dst.SchemaName == "" && parsed.SchemaName != "" {
		dst.SchemaName = parsed.SchemaName
	}
	if dst.SchemaName == "" {
		dst.SchemaName = parsed.SchemaName
	}
	dst.Tables = append(dst.Tables, parsed.Tables...)
	if dst.SchemaName == "" {
		dst.SchemaName = parsed.SchemaName
	}
	return nil
}

func parseSchemaBody(body *hclsyntax.Body) (state, error) {
	st := state{}
	for _, block := range body.Blocks {
		switch block.Type {
		case "schema":
			if len(block.Labels) > 0 && st.SchemaName == "" {
				st.SchemaName = block.Labels[0]
			}
		case "table":
			tbl, schemaName, err := parseTableBlock(block)
			if err != nil {
				return state{}, err
			}
			if st.SchemaName == "" {
				st.SchemaName = schemaName
			}
			st.Tables = append(st.Tables, tbl)
		}
	}
	return st, nil
}

func parseTableBlock(block *hclsyntax.Block) (table, string, error) {
	tbl := table{}
	if len(block.Labels) == 0 {
		return tbl, "", fmt.Errorf("table block missing name")
	}
	tbl.Name = block.Labels[0]
	schemaName := "main"
	if attr, ok := block.Body.Attributes["schema"]; ok {
		name, err := traversalToString(attr.Expr)
		if err != nil {
			return tbl, "", err
		}
		if strings.HasPrefix(name, "schema.") {
			schemaName = strings.TrimPrefix(name, "schema.")
		}
	}

	for _, child := range block.Body.Blocks {
		switch child.Type {
		case "column":
			col, err := parseColumnBlock(child)
			if err != nil {
				return tbl, "", err
			}
			tbl.Columns = append(tbl.Columns, col)
		case "primary_key":
			attr, ok := child.Body.Attributes["columns"]
			if !ok {
				continue
			}
			cols, err := parseColumnRefs(attr.Expr)
			if err != nil {
				return tbl, "", err
			}
			tbl.PrimaryKey = cols
		}
	}
	return tbl, schemaName, nil
}

func parseColumnBlock(block *hclsyntax.Block) (column, error) {
	if len(block.Labels) == 0 {
		return column{}, fmt.Errorf("column block missing name")
	}
	col := column{Name: block.Labels[0], NotNull: true}
	if attr, ok := block.Body.Attributes["type"]; ok {
		typ, err := renderExpr(attr.Expr)
		if err != nil {
			return column{}, err
		}
		col.Type = normalizeType(typ)
	}
	if attr, ok := block.Body.Attributes["null"]; ok {
		val, diags := attr.Expr.Value(nil)
		if diags.HasErrors() {
			return column{}, fmt.Errorf(diags.Error())
		}
		col.NotNull = !val.True()
	}
	return col, nil
}

func parseColumnRefs(expr hclsyntax.Expression) ([]string, error) {
	tuple, ok := expr.(*hclsyntax.TupleConsExpr)
	if !ok {
		return nil, fmt.Errorf("unsupported primary key expression")
	}
	var out []string
	for _, item := range tuple.Exprs {
		name, err := traversalToString(item)
		if err != nil {
			return nil, err
		}
		out = append(out, strings.TrimPrefix(name, "column."))
	}
	return out, nil
}

func traversalToString(expr hclsyntax.Expression) (string, error) {
	scope, ok := expr.(*hclsyntax.ScopeTraversalExpr)
	if !ok {
		return "", fmt.Errorf("unsupported traversal expression")
	}
	parts := make([]string, 0, len(scope.Traversal))
	for _, step := range scope.Traversal {
		switch s := step.(type) {
		case hclsyntax.TraverseRoot:
			parts = append(parts, s.Name)
		case hclsyntax.TraverseAttr:
			parts = append(parts, s.Name)
		default:
			return "", fmt.Errorf("unsupported traversal expression")
		}
	}
	return strings.Join(parts, "."), nil
}

func renderExpr(expr hclsyntax.Expression) (string, error) {
	switch e := expr.(type) {
	case *hclsyntax.ScopeTraversalExpr:
		return traversalToString(e)
	case *hclsyntax.FunctionCallExpr:
		args := make([]string, 0, len(e.Args))
		for _, arg := range e.Args {
			text, err := renderExpr(arg)
			if err != nil {
				return "", err
			}
			args = append(args, text)
		}
		return fmt.Sprintf("%s(%s)", e.Name, strings.Join(args, ", ")), nil
	case *hclsyntax.LiteralValueExpr:
		switch {
		case e.Val.Type().FriendlyName() == "number":
			bf := e.Val.AsBigFloat()
			return bf.Text('f', -1), nil
		case e.Val.Type().FriendlyName() == "string":
			return strconv.Quote(e.Val.AsString()), nil
		case e.Val.Type().FriendlyName() == "bool":
			if e.Val.True() {
				return "true", nil
			}
			return "false", nil
		}
	}
	return "", fmt.Errorf("unsupported expression")
}

func ensureSchemaMatch(actual string, desired state) error {
	if desired.SchemaName == "" || desired.SchemaName == actual {
		return nil
	}
	return fmt.Errorf("mismatched HCL and database schemas: %q <> %q", actual, desired.SchemaName)
}

func diffStates(current, desired state) []operation {
	currentByName := map[string]table{}
	desiredByName := map[string]table{}
	for _, tbl := range current.Tables {
		currentByName[tbl.Name] = tbl
	}
	for _, tbl := range desired.Tables {
		desiredByName[tbl.Name] = tbl
	}

	var ops []operation
	for _, tbl := range desired.Tables {
		cur, ok := currentByName[tbl.Name]
		if !ok {
			ops = append(ops, operation{Kind: opCreate, Table: tbl})
			continue
		}
		if !tablesEqual(cur, tbl) {
			ops = append(ops, operation{Kind: opDrop, Table: cur})
			ops = append(ops, operation{Kind: opCreate, Table: tbl})
		}
	}
	for _, tbl := range current.Tables {
		if _, ok := desiredByName[tbl.Name]; ok {
			continue
		}
		ops = append(ops, operation{Kind: opDrop, Table: tbl})
	}
	return ops
}

func tablesEqual(a, b table) bool {
	if a.Name != b.Name || len(a.Columns) != len(b.Columns) || len(a.PrimaryKey) != len(b.PrimaryKey) {
		return false
	}
	for i := range a.Columns {
		if a.Columns[i].Name != b.Columns[i].Name {
			return false
		}
		if normalizeType(a.Columns[i].Type) != normalizeType(b.Columns[i].Type) {
			return false
		}
		if a.Columns[i].NotNull != b.Columns[i].NotNull {
			return false
		}
	}
	for i := range a.PrimaryKey {
		if a.PrimaryKey[i] != b.PrimaryKey[i] {
			return false
		}
	}
	return true
}

func applyOperations(db *sql.DB, ops []operation) error {
	for _, op := range ops {
		if _, err := db.Exec(renderOperationSQLCompact(op)); err != nil {
			return err
		}
	}
	return nil
}

func cleanSQLite(db *sql.DB, tables []table) error {
	if _, err := db.Exec(`PRAGMA foreign_keys = off;`); err != nil {
		return err
	}
	for _, tbl := range tables {
		if _, err := db.Exec(fmt.Sprintf("DROP TABLE `%s`;", tbl.Name)); err != nil {
			return err
		}
	}
	if _, err := db.Exec(`PRAGMA foreign_keys = on;`); err != nil {
		return err
	}
	return nil
}

func renderState(st state, format string) (string, error) {
	if strings.TrimSpace(format) == "" {
		return renderStateHCL(st), nil
	}
	data := inspectFormatDataFromState(st)
	return executeTemplate(format, data, funcMap{
		"json": func(v any) (string, error) {
			buf, err := json.Marshal(v)
			return string(buf), err
		},
		"sql": func(v any, args ...string) (string, error) {
			if st, ok := v.(inspectFormatData); ok {
				return renderInspectSQL(st), nil
			}
			return "", fmt.Errorf("unsupported value for sql")
		},
	})
}

type funcMap = template.FuncMap

func executeTemplate(format string, data any, funcs funcMap) (string, error) {
	tmpl, err := template.New("format").Funcs(funcs).Parse(format)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, data); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func renderStateHCL(st state) string {
	if len(st.Tables) == 0 {
		return fmt.Sprintf("schema %q {\n}\n", st.SchemaName)
	}
	var blocks []string
	for _, tbl := range st.Tables {
		blocks = append(blocks, renderTableHCL(tbl))
	}
	blocks = append(blocks, fmt.Sprintf("schema %q {\n}", st.SchemaName))
	return strings.Join(blocks, "\n") + "\n"
}

func renderTableHCL(tbl table) string {
	var b strings.Builder
	fmt.Fprintf(&b, "table %q {\n", tbl.Name)
	fmt.Fprintf(&b, "  schema = schema.main\n")
	for _, col := range tbl.Columns {
		fmt.Fprintf(&b, "  column %q {\n", col.Name)
		fmt.Fprintf(&b, "    null = false\n")
		fmt.Fprintf(&b, "    type = %s\n", normalizeType(col.Type))
		fmt.Fprintf(&b, "  }\n")
	}
	if len(tbl.PrimaryKey) > 0 {
		fmt.Fprintf(&b, "  primary_key {\n")
		parts := make([]string, 0, len(tbl.PrimaryKey))
		for _, name := range tbl.PrimaryKey {
			parts = append(parts, "column."+name)
		}
		fmt.Fprintf(&b, "    columns = [%s]\n", strings.Join(parts, ", "))
		fmt.Fprintf(&b, "  }\n")
	}
	fmt.Fprintf(&b, "}")
	return b.String()
}

func renderInspectSQL(data inspectFormatData) string {
	var lines []string
	for _, schema := range data.Schemas {
		for _, tbl := range schema.Tables {
			lines = append(lines, fmt.Sprintf("-- create %q table", tbl.Name))
			lines = append(lines, renderCreateSQLCompact(tableFromInspect(tbl)))
		}
	}
	if len(lines) == 0 {
		return ""
	}
	return strings.Join(lines, "\n")
}

func renderPlanCompact(ops []operation) string {
	var lines []string
	for _, op := range ops {
		lines = append(lines, renderOperationComment(op))
		lines = append(lines, renderOperationSQLCompact(op))
	}
	return strings.Join(lines, "\n")
}

func renderPlanPretty(ops []operation) string {
	var lines []string
	lines = append(lines, "-- Planned Changes:")
	for _, op := range ops {
		lines = append(lines, renderOperationComment(op))
		lines = append(lines, renderOperationSQLPretty(op))
	}
	return strings.Join(lines, "\n") + "\n"
}

func renderCleanPlan(tables []table) string {
	var lines []string
	lines = append(lines, "-- Planned Changes:")
	lines = append(lines, "-- Disable the enforcement of foreign-keys constraints")
	lines = append(lines, "PRAGMA foreign_keys = off;")
	for _, tbl := range tables {
		lines = append(lines, fmt.Sprintf("-- Drop %q table", tbl.Name))
		lines = append(lines, fmt.Sprintf("DROP TABLE `%s`;", tbl.Name))
	}
	lines = append(lines, "-- Enable back the enforcement of foreign-keys constraints")
	lines = append(lines, "PRAGMA foreign_keys = on;")
	return strings.Join(lines, "\n") + "\n"
}

func renderOperationComment(op operation) string {
	switch op.Kind {
	case opCreate:
		return fmt.Sprintf("-- Create %q table", op.Table.Name)
	case opDrop:
		return fmt.Sprintf("-- Drop %q table", op.Table.Name)
	default:
		return ""
	}
}

func renderOperationSQLCompact(op operation) string {
	switch op.Kind {
	case opCreate:
		return renderCreateSQLCompact(op.Table)
	case opDrop:
		return fmt.Sprintf("DROP TABLE `%s`;", op.Table.Name)
	default:
		return ""
	}
}

func renderOperationSQLPretty(op operation) string {
	switch op.Kind {
	case opCreate:
		return renderCreateSQLPretty(op.Table)
	case opDrop:
		return fmt.Sprintf("DROP TABLE `%s`;", op.Table.Name)
	default:
		return ""
	}
}

func renderCreateSQLCompact(tbl table) string {
	var parts []string
	for _, col := range tbl.Columns {
		parts = append(parts, fmt.Sprintf("`%s` %s NOT NULL", col.Name, normalizeType(col.Type)))
	}
	if len(tbl.PrimaryKey) > 0 {
		var cols []string
		for _, name := range tbl.PrimaryKey {
			cols = append(cols, fmt.Sprintf("`%s`", name))
		}
		parts = append(parts, fmt.Sprintf("PRIMARY KEY (%s)", strings.Join(cols, ", ")))
	}
	return fmt.Sprintf("CREATE TABLE `%s` (%s);", tbl.Name, strings.Join(parts, ", "))
}

func renderCreateSQLPretty(tbl table) string {
	lines := []string{fmt.Sprintf("CREATE TABLE `%s` (", tbl.Name)}
	for i, col := range tbl.Columns {
		suffix := ","
		if i == len(tbl.Columns)-1 && len(tbl.PrimaryKey) == 0 {
			suffix = ""
		}
		lines = append(lines, fmt.Sprintf("  `%s` %s NOT NULL%s", col.Name, normalizeType(col.Type), suffix))
	}
	if len(tbl.PrimaryKey) > 0 {
		var cols []string
		for _, name := range tbl.PrimaryKey {
			cols = append(cols, fmt.Sprintf("`%s`", name))
		}
		lines = append(lines, fmt.Sprintf("  PRIMARY KEY (%s)", strings.Join(cols, ", ")))
	}
	lines = append(lines, ");")
	return strings.Join(lines, "\n")
}

func normalizeType(t string) string {
	lower := strings.ToLower(strings.TrimSpace(t))
	switch {
	case strings.HasPrefix(lower, "varchar"):
		return "varchar"
	case lower == "integer":
		return "int"
	default:
		return lower
	}
}

func confirmApply() (bool, error) {
	info, err := os.Stdin.Stat()
	if err != nil {
		return false, err
	}
	if info.Mode()&os.ModeCharDevice == 0 {
		return false, nil
	}
	fmt.Print("? Are you sure?: [Apply/Abort] ")
	reader := bufio.NewReader(os.Stdin)
	line, err := reader.ReadString('\n')
	if err != nil && err.Error() != "EOF" {
		return false, err
	}
	line = strings.TrimSpace(strings.ToLower(line))
	return line == "" || line == "apply" || line == "a", nil
}

type inspectFormatData struct {
	Schemas []inspectSchema `json:"schemas"`
}

type inspectSchema struct {
	Name   string         `json:"name"`
	Tables []inspectTable `json:"tables,omitempty"`
}

type inspectTable struct {
	Name       string             `json:"name"`
	Columns    []inspectColumn    `json:"columns,omitempty"`
	PrimaryKey *inspectPrimaryKey `json:"primary_key,omitempty"`
}

type inspectColumn struct {
	Name string `json:"name"`
	Type string `json:"type"`
}

type inspectPrimaryKey struct {
	Parts []inspectPKPart `json:"parts"`
}

type inspectPKPart struct {
	Column string `json:"column"`
}

func inspectFormatDataFromState(st state) inspectFormatData {
	out := inspectFormatData{
		Schemas: []inspectSchema{{Name: st.SchemaName}},
	}
	for _, tbl := range st.Tables {
		entry := inspectTable{Name: tbl.Name}
		for _, col := range tbl.Columns {
			typ := col.RawType
			if typ == "" {
				switch normalizeType(col.Type) {
				case "int":
					typ = "INT"
				default:
					typ = normalizeType(col.Type)
				}
			}
			entry.Columns = append(entry.Columns, inspectColumn{Name: col.Name, Type: typ})
		}
		if len(tbl.PrimaryKey) > 0 {
			entry.PrimaryKey = &inspectPrimaryKey{}
			for _, name := range tbl.PrimaryKey {
				entry.PrimaryKey.Parts = append(entry.PrimaryKey.Parts, inspectPKPart{Column: name})
			}
		}
		out.Schemas[0].Tables = append(out.Schemas[0].Tables, entry)
	}
	return out
}

func tableFromInspect(tbl inspectTable) table {
	out := table{Name: tbl.Name}
	for _, col := range tbl.Columns {
		out.Columns = append(out.Columns, column{Name: col.Name, Type: normalizeType(col.Type), NotNull: true})
	}
	if tbl.PrimaryKey != nil {
		for _, part := range tbl.PrimaryKey.Parts {
			out.PrimaryKey = append(out.PrimaryKey, part.Column)
		}
	}
	return out
}

