package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type rawError struct {
	msg string
}

func (e *rawError) Error() string {
	return e.msg
}

type flagKind int

const (
	flagBool flagKind = iota
	flagString
	flagStrings
)

type flagSpec struct {
	name       string
	short      string
	kind       flagKind
	splitComma bool
}

type parsedFlags struct {
	bools      map[string]bool
	strings    map[string]string
	stringSets map[string][]string
	positionals []string
}

type projectFlags struct {
	config string
	env    string
	vars   []string
}

type inspectOpts struct {
	url     string
	devURL  string
	schemas []string
	exclude []string
	format  string
}

type applyOpts struct {
	url         string
	to          []string
	exclude     []string
	include     []string
	schemas     []string
	devURL      string
	dryRun      bool
	autoApprove bool
	format      string
}

type diffOpts struct {
	from    []string
	to      []string
	devURL  string
	schemas []string
	exclude []string
	include []string
	format  string
}

type cleanOpts struct {
	url         string
	dryRun      bool
	format      string
	autoApprove bool
}

func main() {
	if err := run(os.Args[1:]); err != nil {
		var raw *rawError
		if errors.As(err, &raw) {
			fmt.Fprintln(os.Stderr, raw.msg)
		} else {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		}
		os.Exit(1)
	}
}

func run(args []string) error {
	if len(args) == 0 {
		fmt.Print(rootHelp)
		return nil
	}
	switch args[0] {
	case "-h", "--help", "help":
		return runHelp(args[1:])
	case "--version":
		return &rawError{msg: rootVersionFlagError}
	case "license":
		return runLicense(args[1:])
	case "version":
		return runVersion(args[1:])
	case "schema":
		return runSchema(args[1:])
	case "migrate":
		return runMigrate(args[1:])
	case "completion":
		return runCompletion(args[1:])
	default:
		if strings.HasPrefix(args[0], "-") {
			return fmt.Errorf("unknown flag: %s", args[0])
		}
		return fmt.Errorf("unknown command %q for %q\nRun 'atlas --help' for usage.", args[0], "atlas")
	}
}

func runHelp(args []string) error {
	if len(args) == 0 {
		fmt.Print(rootHelp)
		return nil
	}
	topic := strings.Join(args, " ")
	switch topic {
	case "schema":
		fmt.Print(schemaHelp)
	case "schema fmt":
		fmt.Print(schemaFmtHelp)
	case "schema inspect":
		fmt.Print(schemaInspectHelp)
	case "schema apply":
		fmt.Print(schemaApplyHelp)
	case "schema diff":
		fmt.Print(schemaDiffHelp)
	case "schema clean":
		fmt.Print(schemaCleanHelp)
	case "migrate":
		fmt.Print(migrateHelp)
	case "completion":
		fmt.Print(completionHelp)
	case "completion bash":
		fmt.Print(completionBashHelp)
	case "completion fish":
		fmt.Print(completionFishHelp)
	case "completion powershell":
		fmt.Print(completionPowerShellHelp)
	case "completion zsh":
		fmt.Print(completionZshHelp)
	case "license":
		fmt.Print(licenseHelp)
	case "version":
		fmt.Print(versionHelp)
	default:
		fmt.Printf("Unknown help topic [%s]\n", backtickList(args))
		fmt.Print(rootHelpNoFlags)
	}
	return nil
}

func runLicense(args []string) error {
	if hasHelp(args) {
		fmt.Print(licenseHelp)
		return nil
	}
	fmt.Print(licenseOutput)
	return nil
}

func runVersion(args []string) error {
	if hasHelp(args) {
		fmt.Print(versionHelp)
		return nil
	}
	fmt.Print(versionOutput)
	return nil
}

func runCompletion(args []string) error {
	if len(args) == 0 || hasHelp(args) {
		flags, err := parseFlags(args, []flagSpec{{name: "help", short: "h", kind: flagBool}})
		if err != nil {
			return err
		}
		if len(flags.positionals) == 0 {
			fmt.Print(completionHelp)
			return nil
		}
	}
	shell := args[0]
	switch shell {
	case "bash":
		return runCompletionShell(args[1:], completionBashHelp, bashCompletionScript)
	case "fish":
		return runCompletionShell(args[1:], completionFishHelp, fishCompletionScript)
	case "powershell":
		return runCompletionShell(args[1:], completionPowerShellHelp, powerShellCompletionScript)
	case "zsh":
		return runCompletionShell(args[1:], completionZshHelp, zshCompletionScript)
	default:
		flags, err := parseFlags(args, []flagSpec{{name: "help", short: "h", kind: flagBool}})
		if err != nil {
			return err
		}
		if len(flags.positionals) > 0 {
			fmt.Print(completionHelp)
			return nil
		}
		fmt.Print(completionHelp)
		return nil
	}
}

func runCompletionShell(args []string, helpText, script string) error {
	flags, err := parseFlags(args, []flagSpec{
		{name: "help", short: "h", kind: flagBool},
		{name: "no-descriptions", kind: flagBool},
	})
	if err != nil {
		return err
	}
	if flags.bools["help"] {
		fmt.Print(helpText)
		return nil
	}
	fmt.Print(script)
	if !strings.HasSuffix(script, "\n") {
		fmt.Println()
	}
	return nil
}

func runMigrate(args []string) error {
	persistent := projectFlagSpecs()
	if len(args) == 0 || onlyHelp(args, persistent) {
		if _, err := parseFlags(args, persistent); err != nil {
			return err
		}
		fmt.Print(migrateHelp)
		return nil
	}
	idx, name, found, err := findSubcommand(args, persistent)
	if err != nil {
		return err
	}
	if !found || !isMigrateSubcommand(name) {
		if _, err := parseFlags(args, persistent); err != nil {
			return err
		}
		fmt.Print(migrateHelp)
		return nil
	}
	rest := append([]string{}, args[:idx]...)
	rest = append(rest, args[idx+1:]...)
	flags, err := parseFlags(rest, append(persistent, flagSpec{name: "help", short: "h", kind: flagBool}))
	if err != nil {
		return err
	}
	if flags.bools["help"] || true {
		fmt.Print(migrateLeafHelp(name))
		return nil
	}
}

func runSchema(args []string) error {
	persistent := projectFlagSpecs()
	if len(args) == 0 || onlyHelp(args, persistent) {
		if _, err := parseFlags(args, persistent); err != nil {
			return err
		}
		fmt.Print(schemaHelp)
		return nil
	}
	idx, name, found, err := findSubcommand(args, persistent)
	if err != nil {
		return err
	}
	if !found || !isSchemaSubcommand(name) {
		if _, err := parseFlags(args, persistent); err != nil {
			return err
		}
		fmt.Print(schemaHelp)
		return nil
	}
	rest := append([]string{}, args[:idx]...)
	rest = append(rest, args[idx+1:]...)
	switch name {
	case "fmt":
		return runSchemaFmt(rest)
	case "inspect":
		return runSchemaInspect(rest)
	case "apply":
		return runSchemaApply(rest)
	case "diff":
		return runSchemaDiff(rest)
	case "clean":
		return runSchemaClean(rest)
	default:
		fmt.Print(schemaHelp)
		return nil
	}
}

func runSchemaFmt(args []string) error {
	flags, err := parseFlags(args, append(projectFlagSpecs(), flagSpec{name: "help", short: "h", kind: flagBool}))
	if err != nil {
		return err
	}
	if flags.bools["help"] {
		fmt.Print(schemaFmtHelp)
		return nil
	}
	paths := flags.positionals
	if len(paths) == 0 {
		paths = []string{"."}
	}
	for _, path := range paths {
		info, err := os.Stat(path)
		if err != nil {
			return err
		}
		if info.IsDir() {
			entries, err := os.ReadDir(path)
			if err != nil {
				return err
			}
			for _, entry := range entries {
				if entry.IsDir() || filepath.Ext(entry.Name()) != ".hcl" {
					continue
				}
				target := filepath.Join(path, entry.Name())
				changed, err := formatHCLPath(target)
				if err != nil {
					return err
				}
				if changed {
					fmt.Println(target)
				}
			}
			continue
		}
		if filepath.Ext(path) != ".hcl" {
			continue
		}
		changed, err := formatHCLPath(path)
		if err != nil {
			return err
		}
		if changed {
			fmt.Println(path)
		}
	}
	return nil
}

func runSchemaInspect(args []string) error {
	flags, err := parseFlags(args, append(projectFlagSpecs(),
		flagSpec{name: "help", short: "h", kind: flagBool},
		flagSpec{name: "url", short: "u", kind: flagString},
		flagSpec{name: "dev-url", kind: flagString},
		flagSpec{name: "schema", short: "s", kind: flagStrings, splitComma: true},
		flagSpec{name: "exclude", kind: flagStrings, splitComma: true},
		flagSpec{name: "format", kind: flagString},
	))
	if err != nil {
		return err
	}
	if flags.bools["help"] {
		fmt.Print(schemaInspectHelp)
		return nil
	}
	cfg := projectFlagsFrom(flags)
	env, err := resolveProjectEnv(cfg)
	if err != nil {
		return err
	}
	opts := inspectOpts{
		url:     pickString(flags.strings["url"], env.URL),
		devURL:  pickString(flags.strings["dev-url"], env.DevURL),
		schemas: pickStrings(flags.stringSets["schema"], env.Schemas),
		exclude: flags.stringSets["exclude"],
		format:  flags.strings["format"],
	}
	if opts.url == "" {
		return requiredFlagsError("url")
	}
	ref, err := parseResource(opts.url)
	if err != nil {
		return err
	}
	if ref.scheme != "sqlite" {
		return fmt.Errorf("unsupported driver %q", ref.scheme)
	}
	db, foreignKeys, err := openSQLiteDB(ref.body)
	if err != nil {
		return err
	}
	defer db.Close()
	if foreignKeys {
		if err := db.Exec("PRAGMA foreign_keys = on;"); err != nil {
			return err
		}
	}
	state, err := inspectSQLite(db)
	if err != nil {
		return err
	}
	out, err := renderInspect(state, opts.format)
	if err != nil {
		return err
	}
	fmt.Print(out)
	return nil
}

func runSchemaApply(args []string) error {
	flags, err := parseFlags(args, append(projectFlagSpecs(),
		flagSpec{name: "help", short: "h", kind: flagBool},
		flagSpec{name: "url", short: "u", kind: flagString},
		flagSpec{name: "to", kind: flagStrings},
		flagSpec{name: "exclude", kind: flagStrings, splitComma: true},
		flagSpec{name: "include", kind: flagStrings, splitComma: true},
		flagSpec{name: "schema", short: "s", kind: flagStrings, splitComma: true},
		flagSpec{name: "dev-url", kind: flagString},
		flagSpec{name: "dry-run", kind: flagBool},
		flagSpec{name: "auto-approve", kind: flagBool},
		flagSpec{name: "format", kind: flagString},
		flagSpec{name: "tx-mode", kind: flagString},
		flagSpec{name: "plan", kind: flagString},
		flagSpec{name: "edit", kind: flagBool},
		flagSpec{name: "lock-timeout", kind: flagString},
	))
	if err != nil {
		return err
	}
	if flags.bools["help"] {
		fmt.Print(schemaApplyHelp)
		return nil
	}
	cfg := projectFlagsFrom(flags)
	env, err := resolveProjectEnv(cfg)
	if err != nil {
		return err
	}
	opts := applyOpts{
		url:         pickString(flags.strings["url"], env.URL),
		to:          flags.stringSets["to"],
		exclude:     flags.stringSets["exclude"],
		include:     flags.stringSets["include"],
		schemas:     pickStrings(flags.stringSets["schema"], env.Schemas),
		devURL:      pickString(flags.strings["dev-url"], env.DevURL),
		dryRun:      flags.bools["dry-run"],
		autoApprove: flags.bools["auto-approve"],
		format:      flags.strings["format"],
	}
	if opts.url == "" {
		return requiredFlagsError("url")
	}
	if len(opts.to) == 0 {
		return requiredFlagsError("to")
	}
	ref, err := parseResource(opts.url)
	if err != nil {
		return err
	}
	if ref.scheme != "sqlite" {
		return fmt.Errorf("unsupported driver %q", ref.scheme)
	}
	desired, err := loadStateFromResources(opts.to)
	if err != nil {
		return err
	}
	if err := ensureSchemaMatch("main", desired); err != nil {
		return err
	}
	db, foreignKeys, err := openSQLiteDB(ref.body)
	if err != nil {
		return err
	}
	defer db.Close()
	if foreignKeys {
		if err := db.Exec("PRAGMA foreign_keys = on;"); err != nil {
			return err
		}
	}
	current, err := inspectSQLite(db)
	if err != nil {
		return err
	}
	ops := diffStates(current, desired)
	if len(ops) == 0 {
		fmt.Println("Schema is synced, no changes to be made")
		return nil
	}
	fmt.Print(renderPrettyPlan(ops))
	if opts.dryRun {
		return nil
	}
	if !opts.autoApprove {
		ok, err := confirmApply()
		if err != nil {
			return err
		}
		if !ok {
			return nil
		}
	}
	return applyOperations(db, ops)
}

func runSchemaDiff(args []string) error {
	flags, err := parseFlags(args, append(projectFlagSpecs(),
		flagSpec{name: "help", short: "h", kind: flagBool},
		flagSpec{name: "from", short: "f", kind: flagStrings},
		flagSpec{name: "to", kind: flagStrings},
		flagSpec{name: "dev-url", kind: flagString},
		flagSpec{name: "schema", short: "s", kind: flagStrings, splitComma: true},
		flagSpec{name: "exclude", kind: flagStrings, splitComma: true},
		flagSpec{name: "include", kind: flagStrings, splitComma: true},
		flagSpec{name: "format", kind: flagString},
	))
	if err != nil {
		return err
	}
	if flags.bools["help"] {
		fmt.Print(schemaDiffHelp)
		return nil
	}
	cfg := projectFlagsFrom(flags)
	if _, err := resolveProjectEnv(cfg); err != nil {
		return err
	}
	opts := diffOpts{
		from:    flags.stringSets["from"],
		to:      flags.stringSets["to"],
		devURL:  flags.strings["dev-url"],
		schemas: flags.stringSets["schema"],
		exclude: flags.stringSets["exclude"],
