	flags, err := parseFlags(args, append(projectFlagSpecs(),
		flagSpec{name: "help", short: "h", kind: flagBool},
		flagSpec{name: "url", short: "u", kind: flagString},
		flagSpec{name: "dry-run", kind: flagBool},
		flagSpec{name: "format", kind: flagString},
		flagSpec{name: "auto-approve", kind: flagBool},
	))
	if err != nil {
