func parseFlags(args []string, specs []flagSpec) (parsedFlags, error) {
	long := map[string]flagSpec{}
	short := map[string]flagSpec{}
	for _, spec := range specs {
		long[spec.name] = spec
		if spec.short != "" {
			short[spec.short] = spec
		}
	}
	out := parsedFlags{
		bools:      map[string]bool{},
		strings:    map[string]string{},
		stringSets: map[string][]string{},
	}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			out.positionals = append(out.positionals, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "--") {
			name, value, hasValue := strings.Cut(strings.TrimPrefix(arg, "--"), "=")
			spec, ok := long[name]
			if !ok {
				return out, fmt.Errorf("unknown flag: --%s", name)
			}
			switch spec.kind {
			case flagBool:
				if hasValue {
					return out, fmt.Errorf("unknown flag: %s", arg)
				}
				out.bools[spec.name] = true
			case flagString, flagStrings:
				if !hasValue {
					if i+1 >= len(args) {
						value = ""
					} else {
						i++
						value = args[i]
					}
				}
				addFlagValue(&out, spec, value)
			}
			continue
		}
		if strings.HasPrefix(arg, "-") && arg != "-" {
			name := strings.TrimPrefix(arg, "-")
			spec, ok := short[name]
			if !ok {
				return out, fmt.Errorf("unknown flag: -%s", name)
			}
			switch spec.kind {
			case flagBool:
				out.bools[spec.name] = true
			case flagString, flagStrings:
				value := ""
				if i+1 < len(args) {
					i++
					value = args[i]
				}
				addFlagValue(&out, spec, value)
			}
			continue
		}
		out.positionals = append(out.positionals, arg)
	}
	return out, nil
}

func addFlagValue(flags *parsedFlags, spec flagSpec, value string) {
	switch spec.kind {
	case flagString:
		flags.strings[spec.name] = value
	case flagStrings:
		if spec.splitComma {
			parts := strings.Split(value, ",")
			for _, part := range parts {
				if part == "" {
					continue
				}
				flags.stringSets[spec.name] = append(flags.stringSets[spec.name], part)
			}
			return
		}
		flags.stringSets[spec.name] = append(flags.stringSets[spec.name], value)
	}
}

func projectFlagsFrom(flags parsedFlags) projectFlags {
	return projectFlags{
		config: pickString(flags.strings["config"], "file://atlas.hcl"),
		env:    flags.strings["env"],
		vars:   flags.stringSets["var"],
	}
}

func projectFlagSpecs() []flagSpec {
	return []flagSpec{
		{name: "help", short: "h", kind: flagBool},
		{name: "config", short: "c", kind: flagString},
		{name: "env", kind: flagString},
		{name: "var", kind: flagStrings},
	}
}

func onlyHelp(args []string, specs []flagSpec) bool {
	for _, arg := range args {
		if arg == "-h" || arg == "--help" {
			continue
		}
		if strings.HasPrefix(arg, "-") {
			name := strings.TrimLeft(arg, "-")
			if strings.Contains(name, "=") {
				name = strings.SplitN(name, "=", 2)[0]
			}
			if isPersistentFlag(name, specs) {
				continue
			}
		}
		return false
	}
	return true
}

func findSubcommand(args []string, persistent []flagSpec) (int, string, bool, error) {
	expectValueFor := ""
	for i, arg := range args {
		if expectValueFor != "" {
			expectValueFor = ""
			continue
		}
		if strings.HasPrefix(arg, "--") {
			name := strings.TrimPrefix(arg, "--")
			if strings.Contains(name, "=") {
				name = strings.SplitN(name, "=", 2)[0]
			} else if isValueFlag(name, persistent) {
				expectValueFor = name
			}
			if arg == "--help" {
				continue
			}
			if !isPersistentFlag(name, persistent) {
				return 0, "", false, fmt.Errorf("unknown flag: --%s", name)
			}
			continue
		}
		if strings.HasPrefix(arg, "-") && arg != "-" {
			name := strings.TrimPrefix(arg, "-")
			if arg == "-h" {
				continue
			}
			if !isPersistentShort(name, persistent) {
				return 0, "", false, fmt.Errorf("unknown flag: -%s", name)
			}
			if shortNeedsValue(name, persistent) {
				expectValueFor = name
			}
			continue
		}
		return i, arg, true, nil
	}
	return 0, "", false, nil
}

func isPersistentFlag(name string, specs []flagSpec) bool {
	for _, spec := range specs {
		if spec.name == name {
			return true
		}
	}
	return false
}

func isPersistentShort(name string, specs []flagSpec) bool {
	for _, spec := range specs {
		if spec.short == name {
			return true
		}
	}
	return false
}

func isValueFlag(name string, specs []flagSpec) bool {
	for _, spec := range specs {
		if spec.name == name {
			return spec.kind != flagBool
		}
	}
	return false
}

func shortNeedsValue(name string, specs []flagSpec) bool {
	for _, spec := range specs {
		if spec.short == name {
			return spec.kind != flagBool
		}
	}
	return false
}

func isSchemaSubcommand(name string) bool {
	switch name {
	case "apply", "clean", "diff", "fmt", "inspect":
		return true
	default:
		return false
	}
}

func isMigrateSubcommand(name string) bool {
	switch name {
	case "apply", "diff", "hash", "import", "lint", "new", "set", "status", "validate":
		return true
	default:
		return false
	}
}

func hasHelp(args []string) bool {
	for _, arg := range args {
		if arg == "-h" || arg == "--help" {
			return true
		}
	}
	return false
}

func requiredFlagsError(names ...string) error {
	quoted := make([]string, len(names))
	for i, name := range names {
		quoted[i] = fmt.Sprintf("%q", name)
	}
	return fmt.Errorf("required flag(s) %s not set", strings.Join(quoted, ", "))
}

func parseResource(raw string) (resourceRef, error) {
	idx := strings.Index(raw, "://")
	if idx < 0 {
		return resourceRef{}, fmt.Errorf("missing scheme. See: https://atlasgo.io/url")
	}
	return resourceRef{scheme: raw[:idx], body: raw[idx+3:]}, nil
}

func pickString(primary, fallback string) string {
	if primary != "" {
		return primary
	}
	return fallback
}

func pickStrings(primary, fallback []string) []string {
	if len(primary) > 0 {
		return primary
	}
	return fallback
}

func backtickList(parts []string) string {
	out := make([]string, len(parts))
	for i, part := range parts {
		out[i] = fmt.Sprintf("`%s`", part)
	}
	return strings.Join(out, " ")
}

func confirmApply() (bool, error) {
	info, err := os.Stdin.Stat()
	if err != nil {
		return false, err
	}
	if info.Mode()&os.ModeCharDevice == 0 {
		return false, nil
	}
	fmt.Print("? Are you sure?: [Apply/Abort] ")
	var line string
	if _, err := fmt.Fscanln(os.Stdin, &line); err != nil {
		return true, nil
	}
	line = strings.ToLower(strings.TrimSpace(line))
	return line == "" || line == "apply" || line == "a", nil
}

func renderInspect(st schemaState, format string) (string, error) {
	switch strings.TrimSpace(format) {
	case "":
		return renderInspectHCL(st), nil
	case "{{ json . }}":
		data := inspectJSONFromState(st)
		buf, err := json.Marshal(data)
		return string(buf), err
	case "{{ sql . }}":
		return renderInspectSQL(st), nil
	default:
		return "", fmt.Errorf("unsupported format")
	}
}

func renderInspectHCL(st schemaState) string {
	if len(st.Tables) == 0 {
		return fmt.Sprintf("schema %q {\n}\n", st.SchemaName)
	}
	var blocks []string
	for _, tbl := range st.Tables {
		blocks = append(blocks, renderInspectTable(tbl))
	}
	blocks = append(blocks, fmt.Sprintf("schema %q {\n}", st.SchemaName))
	return strings.Join(blocks, "\n") + "\n"
}

func renderInspectTable(tbl tableDef) string {
	var b strings.Builder
	fmt.Fprintf(&b, "table %q {\n", tbl.Name)
	fmt.Fprintf(&b, "  schema = schema.main\n")
	for _, col := range tbl.Columns {
		fmt.Fprintf(&b, "  column %q {\n", col.Name)
		fmt.Fprintf(&b, "    null = false\n")
		fmt.Fprintf(&b, "    type = %s\n", normalizeType(col.Type))
		fmt.Fprintf(&b, "  }\n")
	}
	if len(tbl.PrimaryKey) > 0 {
		fmt.Fprintf(&b, "  primary_key {\n")
		var cols []string
		for _, name := range tbl.PrimaryKey {
			cols = append(cols, "column."+name)
		}
		fmt.Fprintf(&b, "    columns = [%s]\n", strings.Join(cols, ", "))
		fmt.Fprintf(&b, "  }\n")
	}
	fmt.Fprintf(&b, "}")
	return b.String()
}

func renderInspectSQL(st schemaState) string {
	var lines []string
	for _, tbl := range st.Tables {
		lines = append(lines, fmt.Sprintf("-- create %q table", tbl.Name))
		lines = append(lines, renderCreateCompact(tbl))
	}
	return strings.Join(lines, "\n")
}

func renderPrettyPlan(ops []schemaOp) string {
	lines := []string{"-- Planned Changes:"}
	for _, op := range ops {
		lines = append(lines, op.Comment())
		lines = append(lines, op.SQLPretty())
	}
	return strings.Join(lines, "\n") + "\n"
}

func renderCompactPlan(ops []schemaOp) string {
	lines := make([]string, 0, len(ops)*2)
	for _, op := range ops {
		lines = append(lines, op.Comment())
		lines = append(lines, op.SQLCompact())
	}
	return strings.Join(lines, "\n")
}

func renderCleanPlan(tables []tableDef) string {
	lines := []string{
		"-- Planned Changes:",
		"-- Disable the enforcement of foreign-keys constraints",
		"PRAGMA foreign_keys = off;",
	}
	for _, tbl := range tables {
		lines = append(lines, fmt.Sprintf("-- Drop %q table", tbl.Name))
		lines = append(lines, fmt.Sprintf("DROP TABLE `%s`;", tbl.Name))
	}
	lines = append(lines, "-- Enable back the enforcement of foreign-keys constraints")
	lines = append(lines, "PRAGMA foreign_keys = on;")
	return strings.Join(lines, "\n") + "\n"
}

func renderCreateCompact(tbl tableDef) string {
	parts := make([]string, 0, len(tbl.Columns)+1)
	for _, col := range tbl.Columns {
		parts = append(parts, fmt.Sprintf("`%s` %s NOT NULL", col.Name, normalizeType(col.Type)))
	}
	if len(tbl.PrimaryKey) > 0 {
		var cols []string
		for _, name := range tbl.PrimaryKey {
			cols = append(cols, fmt.Sprintf("`%s`", name))
		}
		parts = append(parts, fmt.Sprintf("PRIMARY KEY (%s)", strings.Join(cols, ", ")))
	}
	return fmt.Sprintf("CREATE TABLE `%s` (%s);", tbl.Name, strings.Join(parts, ", "))
}

func renderCreatePretty(tbl tableDef) string {
	lines := []string{fmt.Sprintf("CREATE TABLE `%s` (", tbl.Name)}
	for i, col := range tbl.Columns {
		suffix := ","
		if i == len(tbl.Columns)-1 && len(tbl.PrimaryKey) == 0 {
			suffix = ""
		}
		lines = append(lines, fmt.Sprintf("  `%s` %s NOT NULL%s", col.Name, normalizeType(col.Type), suffix))
	}
	if len(tbl.PrimaryKey) > 0 {
		var cols []string
		for _, name := range tbl.PrimaryKey {
			cols = append(cols, fmt.Sprintf("`%s`", name))
		}
		lines = append(lines, fmt.Sprintf("  PRIMARY KEY (%s)", strings.Join(cols, ", ")))
	}
	lines = append(lines, ");")
	return strings.Join(lines, "\n")
}

func normalizeType(t string) string {
	lower := strings.ToLower(strings.TrimSpace(t))
	switch {
	case strings.HasPrefix(lower, "varchar"):
		return "varchar"
	case lower == "integer":
		return "int"
	default:
		return lower
	}
}

type inspectJSON struct {
	Schemas []inspectJSONSchema `json:"schemas"`
}

type inspectJSONSchema struct {
	Name   string             `json:"name"`
	Tables []inspectJSONTable `json:"tables,omitempty"`
}

type inspectJSONTable struct {
	Name       string               `json:"name"`
	Columns    []inspectJSONColumn  `json:"columns,omitempty"`
	PrimaryKey *inspectJSONPrimary  `json:"primary_key,omitempty"`
}

type inspectJSONColumn struct {
	Name string `json:"name"`
	Type string `json:"type"`
}

type inspectJSONPrimary struct {
	Parts []inspectJSONPart `json:"parts"`
}

type inspectJSONPart struct {
	Column string `json:"column"`
}

func inspectJSONFromState(st schemaState) inspectJSON {
	out := inspectJSON{Schemas: []inspectJSONSchema{{Name: st.SchemaName}}}
	for _, tbl := range st.Tables {
		entry := inspectJSONTable{Name: tbl.Name}
		for _, col := range tbl.Columns {
			raw := col.RawType
			if raw == "" {
				raw = normalizeType(col.Type)
				if raw == "int" {
					raw = "INT"
				}
			}
			entry.Columns = append(entry.Columns, inspectJSONColumn{Name: col.Name, Type: raw})
		}
		if len(tbl.PrimaryKey) > 0 {
			entry.PrimaryKey = &inspectJSONPrimary{}
			for _, name := range tbl.PrimaryKey {
				entry.PrimaryKey.Parts = append(entry.PrimaryKey.Parts, inspectJSONPart{Column: name})
			}
		}
		out.Schemas[0].Tables = append(out.Schemas[0].Tables, entry)
	}
	return out
}

